window.CHAPTERS=window.CHAPTERS||{};window.CHAPTERS["ch12"]={"id": "ch12", "title": "第七章 细胞衰老与凋亡", "sub": "翟中和《细胞生物学》第4版 · 教师课件逐页详解", "sub2": "衰老 · 凋亡 · 自噬", "modules": [{"i": 0, "name": "绪论 · 概览", "slides": [{"i": 0, "sec": "", "title": "第7讲       细胞衰老与凋亡", "notes": "1. Hayflick界限\n2. 衰老细胞结构变化\n3. 细胞衰老的分子机制\n1. 细胞凋亡与坏死\n2. 形态学及生化特征\n3. 研究方法\n4. 细胞凋亡的机理", "page": 1, "level": "掌握", "img": "assets/img/ch12/p001.jpg", "anim": null, "fig": null, "points": ["细胞衰老(cell senescence, cell aging)", "细胞凋亡(apoptosis)"], "check": {"q": "关于「第7讲 细胞衰老与凋亡」，下列说法正确的是（　）", "o": ["A. 细胞衰老(cell senescence, cell aging)", "B. 细胞凋亡是一个主动的由基因决定的自动结束", "C. 核纤层蛋白，使位于细胞核膜下的核纤层网络", "D. 细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。"], "a": "A", "e": "本页要点：细胞衰老(cell senescence, cell aging)"}, "cards": null}, {"i": 1, "sec": "", "title": "•1958 年， Leonard Hayflick证实大多", "notes": "数正常细胞只能进行有限次数的分裂。\nLifespan.\na | Young cells in phase II at\npopulation doubling 20.\nb | Old cells in phase III at\npopulation doubling 55.\nNat Rev Mol Cell Biol , 2000, 1(1): 72-76", "page": 2, "level": "掌握", "img": "assets/img/ch12/p002.jpg", "anim": null, "fig": null, "points": ["Somatic Cells(体细胞) Have a Finite"], "check": {"q": "关于「•1958 年， Leonard Hayflic…」，下列说法正确的是（　）", "o": ["A. 生殖干细胞和癌细胞内端粒酶活性高。", "B. Somatic Cells(体细胞) Have a Finite", "C. 变 态：蝌蚪 →→ 青蛙", "D. 自由基：原子核外层轨道上具有不成对电子的分子"], "a": "B", "e": "本页要点：Somatic Cells(体细胞) Have a Finite"}, "cards": null}, {"i": 2, "sec": "", "title": "Part I   细胞衰老 (cell senescence)", "notes": "1   Hayflick 界限\nHayflick 界限(Hayflick limitation):\n细胞, 至少是培养的大多数正常体细胞, 无论怎样完善培养条件，\n都不能无限增殖，其增殖能力是有一定界限的【平均40-60代】。\n(1961年)\n胞内部因素决定细胞的衰老；体外培养的二倍体细胞，是细胞\n核决定细胞的衰老。\n【结合课本/笔记】●细胞衰老的分子机理一、Hayflick界限(Hayflick Limitation）●概念：关于细胞增殖能力和寿命是有限的观点。细胞，至少是培养的二倍体细胞，不是不死的，而是有一定的寿命；它们的增殖能力不是无限的，而是有一定的界限，这就是 Hayflick界限◆ 癌细胞或培养的细胞系是不正常细胞，其染色体数目或形态已经不同于原先的细胞◆ 细胞的增殖能力与供体年龄有关◆ 物种寿命与培养细胞寿命之间存在着一定的关系●二倍体细胞的衰老是由细胞本身决定的◆决定细胞衰老的因素在细胞内部，而不是外部的环境◆是细胞核而不是细胞质决定了细胞衰老", "page": 3, "level": "掌握", "img": "assets/img/ch12/p003.jpg", "anim": null, "fig": null, "points": ["物种寿命与培养细胞(的传代次数)之间存在正相关的关系。", "衰老的原因在于细胞本身：就细胞内外环境因素而言，是细"], "check": {"q": "关于「Part I 细胞衰老 (cell senesc…」，下列说法正确的是（　）", "o": ["A. The nematode Caenorhabditis elegans was an ideal model", "B. 依赖于凋亡蛋白酶-Caspase的途径", "C. 物种寿命与培养细胞(的传代次数)之间存在正相关的关系。", "D. 以上说法均不完全"], "a": "C", "e": "本页要点：物种寿命与培养细胞(的传代次数)之间存在正相关的关系。"}, "cards": null}, {"i": 3, "sec": "", "title": "2   衰老细胞的特点", "notes": "一 细胞停止分裂，并且该停滞是不可逆的。\n二 衰老细胞结构变化\nDifferentiation in\nculture of primary\nmouse satellite cell\n(myoblast 成肌细\n胞) into muscle\ncells.", "page": 4, "level": "掌握", "img": "assets/img/ch12/p004.jpg", "anim": null, "fig": null, "points": ["细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。", "-半乳糖苷酶(溶酶体水解酶)活化。", "线粒体体积膨大但数量减少; mtDNA缺失突变。", "脂褐素生成，色素颗粒沉积", "细胞质膜中胆固醇/磷脂比值升高，流动性减弱。"], "check": {"q": "关于「衰老细胞的特点」，下列说法正确的是（　）", "o": ["A. The effector protein in the apoptotic pathway are", "B. 抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；", "C. 外源途径活化Caspase-8", "D. 细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。"], "a": "D", "e": "本页要点：细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。"}, "cards": null}], "mcq": [{"id": "ch12_mcq_4", "mod": "绪论 · 概览", "modI": 0, "q": "关于细胞凋亡与坏死的区别，下列说法错误的是（       ）。", "o": ["A．细胞凋亡和细胞坏死都是细胞程序性主动性死亡", "B．凋亡细胞和坏死细胞 DNA 电泳都呈“梯状”", "C．细胞凋亡时不伴有局部的炎症反应；而细胞坏死时伴有局部的炎症反应", "D．细胞凋亡时，胞膜及细胞器相对完整；细胞坏死时，胞膜破裂细胞结构溶解 【答案】B  【解析】凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。"], "a": "B", "e": "凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_5", "mod": "绪论 · 概览", "modI": 0, "q": "下列哪个选项不是衰老细胞结构的变化？（      ）", "o": ["A．有序排列的内质网不复存在，内质网成分弥散性的分布于核周胞质中", "B．线粒体的数量减少而体积增大，内容物呈现网状化并形成多囊体", "C．致密体数量大大减少，几近消失", "D．质膜处于凝胶相或固相；细胞间间隙连接减少 【答案】C  【解析】致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。"], "a": "C", "e": "致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_6", "mod": "绪论 · 概览", "modI": 0, "q": "对于体外培养的人二倍体细胞，决定其衰老的主要因素是（         ）。", "o": ["A．细胞培养的外环境", "B．细胞核", "C．细胞质", "D．以上都不是 【答案】B  【解析】Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。"], "a": "B", "e": "Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。", "kp": "ch12_s0_2"}, {"id": "ch12_mcq_7", "mod": "绪论 · 概览", "modI": 0, "q": "根据细胞的寿命可以粗略地分为三类：①寿命接近于动物的整体寿命；②缓慢更新的细 胞，其寿命比机体的寿命短；③快速更新的细胞。下列细胞中，属于第一类的细胞是（         ）。", "o": ["A．神经元、脂肪细胞、肌细胞", "B．肝细胞、胃壁细胞", "C．表皮细胞、红细胞和白细胞", "D．肾皮质细胞、骨细胞、角膜上皮细胞 【答案】A  【解析】胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。"], "a": "A", "e": "胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。", "kp": "ch12_s0_2"}, {"id": "ch12_mcq_9", "mod": "绪论 · 概览", "modI": 0, "q": "下列不属于细胞衰老的特征的是（      ）。", "o": ["A．线粒体数目减少，核膜皱襞", "B．核明显变化为核固缩，常染色质减少", "C．脂褐素减少，细胞代谢能力下降", "D．原生质减少，细胞形状改变 【答案】C  【解析】细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。"], "a": "C", "e": "细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_13", "mod": "绪论 · 概览", "modI": 0, "q": "下列哪项不属于细胞衰老的特征？（                   ）", "o": ["A．原生质减少，细胞形状改变", "B．细胞膜磷脂含量下降，胆固醇含量上升", "C．线粒体数目减少，核膜内折", "D．脂褐素减少，细胞代谢能力下降 【答案】D  【解析】细胞衰老的特征之一是细胞色素颗粒沉积增多：如脂褐素在胞浆中沉积随老年化过 程而增加，在肝细胞、肌细胞和神经细胞中的积聚更为明显。"], "a": "D", "e": "细胞衰老的特征之一是细胞色素颗粒沉积增多：如脂褐素在胞浆中沉积随老年化过 程而增加，在肝细胞、肌细胞和神经细胞中的积聚更为明显。", "kp": "ch12_s0_0"}], "judge": [{"id": "ch12_judge_1", "modI": 0, "q": "通常情况下，体外培养的成纤维细胞的增殖能力与供体年龄有关。（         ）", "a": "对", "e": "如从胎儿肺得到的成纤维细胞可在体外条件下传代 50 次，而从成人肺得到的成纤 维细胞只能传代 20 次。", "kp": "ch12_s0_2"}, {"id": "ch12_judge_8", "modI": 0, "q": "通常未分化细胞的核质比高而衰老细胞的核质比低。（         ）", "a": "错", "e": "衰老细胞内水分减少，致使细胞脱水收缩，体积变小，染色质固化，核膜内折，所 以核质比高。", "kp": "ch12_s0_3"}], "fill": [{"id": "ch12_fill_4", "modI": 0, "q": "细胞衰老的主要学说有______和______。", "a": "氧自由基理论；有丝分裂钟学说", "kp": "ch12_s0_0"}, {"id": "ch12_fill_5", "modI": 0, "q": "衰老是机体在退化时期生理功能下降和紊乱的综合表现，是不可逆的生命过程。就其产 生的性质来说，有三种不同的类型：（1）______衰老；（2）______衰老；（3）______衰 老。", "a": "生理性；病理性；心理性", "kp": "ch12_s0_3"}, {"id": "ch12_fill_8", "modI": 0, "q": "1961 年，Hayflick 发现体外培养的人成纤维细胞具有增殖分裂的极限。来自胚胎的成纤 维细胞分裂传代______次后开始衰老和死亡，而来自成年组织中的成纤维细胞只能培养 ______次就开始死亡。", "a": "50；15～30", "kp": "ch12_s0_2"}, {"id": "ch12_fill_11", "modI": 0, "q": "细胞衰老机理的假说可以归纳为两类：______和______。", "a": "复制衰老；胁迫诱导的早熟性衰老", "kp": "ch12_s0_0"}, {"id": "ch12_fill_14", "modI": 0, "q": "酵母细胞衰老的机制是______。", "a": "ERC 的积累", "kp": "ch12_s0_0"}], "short": [{"id": "ch12_short_3", "modI": 0, "q": "简述细胞凋亡与坏死在形态学上的主要区别。", "a": "两者在形态学上的主要区别是：细胞凋亡过程中，整个细胞固缩，细胞膜反折，包裹断 裂的染色质片断或细胞器，然后逐渐分离，形成众多的凋亡小体，凋亡小体则为邻近的细胞 所吞噬，整个过程中，细胞膜的整合性保持良好，死亡细胞的内容物不会逸散到胞外环境中， 不引发炎症反应。在细胞坏死时，细胞体积膨胀，细胞膜发生渗漏，细胞的内容物释放到细 胞外，导致炎症的发生。", "kp": "ch12_s0_0"}, {"id": "ch12_short_4", "modI": 0, "q": "肿瘤细胞中端粒酶的活性较高，而在正常细胞中检测不到明显的端粒酶活性，这与著名 的 Hayflick 界限有什么关系？", "a": "（1）端粒是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。随着 细胞的每次分裂，端粒缩短，达到一定的阈值时，细胞进入衰老。端粒酶是一种核糖核蛋白 酶，由 RNA 和蛋白质组成，端粒酶以自身 RNA 为模板催化端粒 DNA 的形成。肿瘤细胞是 变异的非正常细胞，具有端粒酶活性，从而保证了肿瘤细胞的“不死性”特征。 （2）“永生”或“不死”的肿瘤细胞具有无限增殖能力的这一特点，看似与 Hayflick 界限所持 的观点相矛盾，然而“永生”的肿瘤细胞已被证明是不正常的细胞，它们的染色体数目或形态 已经不同于原先的细胞了，因此肿瘤细胞并不在 Hayflck 界限的范畴之内。", "kp": "ch12_s0_0"}, {"id": "ch12_short_5", "modI": 0, "q": "细胞衰老与机体衰亡有何相关性？", "a": "细胞衰老与机体衰亡对单细胞生物来说是一回事。但对多细胞机体来说，二者有其密切 的相关性。细胞衰老不等于机体衰亡，机体衰亡也并不意味着所有细胞同时衰亡。例如，一 些细胞的衰亡可换来另一些细胞的新生，从而换来机体的勃勃生机。如果机体刚刚死亡，一 些细胞依然存活，可用来做器官移植和组织培养等。总之，机体整体的衰亡是细胞衰亡的反 映，一些细胞的衰老又是机体衰亡的基础和直接原因。", "kp": "ch12_s0_0"}, {"id": "ch12_short_15", "modI": 0, "q": "细胞衰老有哪些特征？", "a": "细胞衰老表现为对环境变化适应能力的降低和维持细胞内环境恒定能力的降低，不仅形 态学结构发生改变，分子水平的变化也显而易见。细胞衰老的主要特征表现如下： （1）在结构上表现为退行性变化，细胞数目减少、细胞体积缩小。细胞内水分减少，从而 使得原生质硬度增加，造成细胞收缩、失去正常形态。细胞质膜流动性降低。而在原生质改 变的同时，细胞核也发生固缩，结构不清，染色质加深，细胞核与细胞质比率减小或核消失。 同时线粒体数量减少而体积增大。 （2）伴随着细胞的衰老，细胞内各种大分子的组成也发生改变，如蛋白质合成下降。细胞 内蛋白质发生糖基化、氨甲酰化、脱氨基等修饰反应，导致蛋白质稳定性、抗原性、可消化 性下降，自由基使蛋白质多肽断裂、交联而变性，氨基酸由左旋变为右旋。酶分子活性中心 被氧化，金属离子 Ca2 、Zn2 、Mg2 、Fe2 等丢失，最终酶失活。 ＋     ＋  ＋  ＋   （3）DNA 复制与转录受到抑制，但也有个别基因会异常激活，端粒 DNA 丢失，线粒体 DNA 特异性缺失，DNA 氧化、断裂、缺失和交联，甲基化程度降低。 （4）mRNA 和 tRNA 含量降低。", "kp": "ch12_s0_0"}, {"id": "ch12_short_17", "modI": 0, "q": "什么是“Hayflick 界限”？", "a": "“Hayflick 界限”是指正常细胞在体外培养的条件下具有有限分裂次数的现象。动物体细 胞在体外可传代的次数与物种的寿命有关，细胞的分裂能力与个体的年龄有关。正常人的成 纤维细胞在体外培养条件下，即使条件适宜，细胞也不能无限制地进行分裂；即使是机体中 可以终生分裂的细胞，在体外培养时也有分裂次数的极限；即使给予丰富的营养、生长因子 和足够的生长空间也是如此。这种在体外培养的细胞增殖传代的能力，反映了细胞在体内的 衰老状况。", "kp": "ch12_s0_0"}], "calc": [{"id": "ch12_calc_1", "modI": 0, "q": "什么是细胞衰老？细胞衰老有哪些特征？", "a": "细胞的衰老是指体外培养的正常细胞经过有限次数的分裂后，停止分裂，细胞形态和生 理代谢活动发生显著改变的现象。 一般指细胞的形态、结构、化学成分和生理功能逐渐衰退的总现细胞衰老的主要特征有如下 几个方面： （1）衰老过程中细胞质膜体系的变化。细胞质膜体系的变化包括：细胞表面电荷的变化， 年老细胞表面蛋白多糖组成的变化，衰老细胞膜的渗漏引起外界钙的大量进入细胞质；内质 网排列变得无序。 （2）衰老过程中细胞骨架体系的变化。细胞骨架被认为是细胞代谢功能的调节者，尤其是 微丝系统与细胞增殖和细胞分化的调节直接相关。细胞骨架的改变包括微丝系统的结构和成 分发生变化和核骨架的变化。 （3）衰老过程中线粒体的变化。研究结果表明，细胞中线粒体的数量随着年龄的增大而减 少。有人认为线粒体是细胞衰老的生物钟。 （4）细胞核的变化。细胞核体积增大，核膜内折；染色质固缩化是衰老细胞核中另一个重 要变化，染色体端粒的变化。 （5）衰老过程中蛋白质合成的变化。在细胞衰老过程中蛋白质合成速度降低，原因是由于 核糖体的效率和准确性降低及蛋白质合成延伸因子的数量和活性降低所造成。另外在细胞衰 老过程中蛋白质合成发生变化的另一个特点是，一些特异蛋白的出现或原有蛋白质发生衰老 有关的结构上的改变。 （6）原生质与水分的减少。细胞到了衰老期，细胞内的生活物质逐渐减少，而原生质中出 现一些非生命物质。另外，衰老细胞常发生水分减少的现象，结果使细胞收缩，体积缩小， 失去正常的球形。 （7）酶的活性与含量的变化。衰老细胞内酶的活性变化和含量的增减，也可能与细胞衰老 有密切关系。 （8）色素的生成和蜡样物质的沉积。许多细胞内色素的生成，随着衰老而增加。有人发现 猕猴的神经细胞内，脂褐素的增加与动物年龄增长存在着平行关系。 强的核外染色物质多，反之，在衰老细胞就少。 （10）核质比例减少。细胞核与细胞质的比例逐渐减小，生长速度也逐渐降低，甚至有的细 胞最后连核都消失掉。", "kp": "ch12_s0_0"}, {"id": "ch12_calc_4", "modI": 0, "q": "你认为细胞衰老的可能原因有哪些？", "a": "细胞衰老是随着时间的推移，细胞增殖能力和生理功能逐渐下降的变化过程。表现为细 胞在形态上发生明显变化，例如：细胞皱缩，质膜透性和脆性提高，线粒体数量减少，染色 质固缩、断裂等。其原因可归纳为以下几点： （1）端粒的缩短。不同组织细胞端粒长度不同，体外培养细胞的端粒长度随着世代的增加 逐渐缩短；并且在正常的体细胞中端粒酶处于失活状态，如果将活化的端粒酶导入正常的人 成纤维细胞并使其持续表达，结果细胞的端粒不再缩短，而此时细胞的复制寿命增加了近 5 倍。这些证据表明，端粒的缩短能够导致细胞的衰老。其作用机制为：端粒的缩短促使细胞 中 p53 含量增加，继而诱导 p21 的表达，从而抑制 CDK 的活性，使得 Rb 不能被磷酸化， 使 E2F 处于失活状态，细胞因此不能从 G1 期进入 S 期，从而引发细胞衰亡。 （2）胁迫诱导。许多刺激因素如氧化损伤、乙醇、离子辐射、丝裂霉素 C 等均能引起细胞 衰老，这一类的细胞衰老称为胁迫诱导的早熟性衰老（SIPS）。这一类衰老的机制均涉及 p53、p21 以及 p16 的信号转导途径。其中氧化损伤引起的细胞衰老最为重要。活性氧自由 基的危害主要表现为脂褐素的形成、线粒体 DNA 的突变、诱导细胞凋亡、蛋白质合成减少 等，这些都可以诱导细胞衰老的产生。 （3）代谢废物累积。这一类的衰老过程主要存在于单细胞生物中，例如酵母细胞随着有丝 分裂的进行，ERC（染色体外的环形拷贝 rDNA）在母细胞中逐渐积累，它可以掠夺 DNA 正常复制和转录所需要的物质，从而抑制细胞生长，使酵母细胞衰老。", "kp": "ch12_s0_0"}], "term": [{"id": "ch12_term_1", "modI": 0, "term": "细胞凋亡（apoptosis）。", "def": "细胞凋亡（apoptosis）是一种有序的或程序性的细胞死亡方式，是细胞接受某些特定信 号刺激后进行的正常生理应答反应。该过程具有典型的形态学和生化特征，凋亡细胞最后以 凋亡小体被吞噬消化。", "kps": "", "kp": "ch12_s0_0"}, {"id": "ch12_term_6", "modI": 0, "term": "成纤维细胞（fibroblast）。", "def": "成纤维细胞是构成纤维性结缔组织的重要成分。细胞特点是：外形长而扁平，常有不规 则的突起；细胞质内含有线粒体、高尔基体、中心体、微脂肪粒等、其他无特殊的分化；细 胞核呈椭圆形，有明显的核仁，细胞核染色性差。成纤维细胞常与胶原纤维紧密相连，因与 胶原纤维的形成有关故称为成纤维细胞。", "kps": "", "kp": "ch12_s0_3"}, {"id": "ch12_term_12", "modI": 0, "term": "Hayflick Limitation", "def": "Hayflick Limitation 的中文名称是 Hayflick 界限。Hayflick 界限是指正常细胞在体外培养 的条件下具有有限分裂次数的现象。动物体细胞在体外可传代的次数与物种的寿命有关，细 胞的分裂能力与个体的年龄有关。正常人的成纤维细胞在体外培养条件下，即使条件适宜， 细胞也不能无限制地进行分裂；即使是机体中可以终生分裂的细胞，在体外培养时也有分裂 次数的极限；即使给予丰富的营养、生长因子和足够的生长空间也是如此。", "kps": "", "kp": "ch12_s0_2"}]}, {"i": 1, "name": "3.1 氧化性损伤学说", "slides": [{"i": 4, "sec": "3.1 氧化性损伤学说", "title": "3 细胞衰老的分子机制", "notes": "3.1 氧化性损伤学说\n或原子基团。其中活性最强的是氧自由基。\n超氧自由基 •O2- ; 羟自由基 •OH ;       H2O2\nIn deed, ROS are purposefully generated by body defense cells\n(e.g. macrophages) to kill pathogens.\nIn humans, excessive or inappropriate generation of ROS has\nbeen implicated in many diverse diseases, heart failure,\nneurodegenerative diseases(神经退行性变疾病), alcohol-induced\nliver disease, diabetes(糖尿病), and aging.", "page": 5, "level": "掌握", "img": "assets/img/ch12/p005.jpg", "anim": null, "fig": null, "points": ["自由基：原子核外层轨道上具有不成对电子的分子", "活性氧基团或分子(reactive oxygen species, ROS)"], "check": {"q": "关于「细胞衰老的分子机制」，下列说法正确的是（　）", "o": ["A. 自由基：原子核外层轨道上具有不成对电子的分子", "B. Nuclear lamina 核纤层蛋白", "C. 细胞衰老(cell senescence, cell aging)", "D. 酶促反应的酶"], "a": "A", "e": "本页要点：自由基：原子核外层轨道上具有不成对电子的分子"}, "cards": null}, {"i": 5, "sec": "3.1 氧化性损伤学说", "title": "人体内自由基的产生有两方面：", "notes": "一环境中的高温、辐射、空气污染、某些化学物质等\n引起的外源性自由基；\n二体内各种代谢反应产生的内源性自由基。\n内源性自由基是人体自由基的主要来源，其产生\n的主要途径有：\n①由线粒体呼吸链电子泄漏产生；\nThe major source of ROS appears to be the electron\ntransport chain.\n②由经过氧化物酶体的多功能氧化酶（MFO）等催化\n底物羟化产生。", "page": 6, "level": "掌握", "img": "assets/img/ch12/p006.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 6, "sec": "3.1 氧化性损伤学说", "title": "⎯具有高度氧化活性，与其他物质反应时力图", "notes": "得电子。活性强，易与细胞内生物大分子发生掠\n夺性反应，使生物大分子发生伤害。\n引起DNA、蛋白质和脂类，尤其是多不饱和脂\n肪酸（polyunsaturated fatty Acids）等大分子物质\n变性和交联，损伤DNA、生物膜、重要的结构蛋白\n和功能蛋白，从而引起衰老各种现象的发生。", "page": 7, "level": "掌握", "img": "assets/img/ch12/p007.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 7, "sec": "3.1 氧化性损伤学说", "title": "人体存在着清除自由基系统", "notes": "SOD(superoxide dismutase): 超氧化物歧化酶\nCu/Zn SOD-cytosol, peroxisome, plastid, root nodules\nMn-SOD, Fe-SOD-mitochondrion, plastid\n过氧化氢酶(catalase, CAT)、过氧化物酶(peroxidase)\n随着年龄增长，SOD、CAT合成量减少，自由基和H2O2积累…\n胱氨酸、巯基乙醇；\n要在线粒体内，阻止其扩散。", "page": 8, "level": "掌握", "img": "assets/img/ch12/p008.jpg", "anim": null, "fig": null, "points": ["酶促反应的酶", "非酶促反应-抗氧化剂(antioxidant)：", "谷胱甘肽、维生素C和E、-胡罗卜素、硒化物、半", "线粒体对自由基的隔离:氧化反应产生的自由基主"], "check": {"q": "关于「人体存在着清除自由基系统」，下列说法正确的是（　）", "o": ["A. 细胞凋亡是一个主动的由基因决定的自动结束", "B. 核纤层蛋白，使位于细胞核膜下的核纤层网络", "C. 细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。", "D. 酶促反应的酶"], "a": "D", "e": "本页要点：酶促反应的酶"}, "cards": null}], "mcq": [], "judge": [], "fill": [], "short": [{"id": "ch12_short_6", "modI": 1, "q": "自由基学说的实验基础是什么？", "a": "以实验动物的寿命作为整体实验的标记物，用饮食技巧来研究自由基与衰老的两个方面， 一方面在饮食中减少某种可以提高自由基水平的化合物，如减少铜离子或不饱和价键的化合 物，从而减少自由基反应对机体的损伤；另一方面，加入某些抗氧化剂，可以抑制自由基反 应，清除自由基。如：2-硫基乙胺（2-MEA）、α-生育酚。饲料中添加抗氧化剂可增加小鼠、 大鼠、果蝇、线虫的寿命。如：将 1.0％（wt／wt）的 2-MEA 加到雄性 LAFl 小鼠的饲料中， 在断奶后很短时间开始喂小鼠可增加平均寿命 30％，相当于人的平均寿命从 73 岁增加到 95 岁。", "kp": "ch12_s1_5"}], "calc": [{"id": "ch12_calc_2", "modI": 1, "q": "自由基如何对细胞产生伤害？", "a": "细胞内自由基的浓度过高时，常与生物大分子发生反应，破坏了生物大分子的结构，从 而伤害了细胞，这些反应包括： （1）自由基与核酸分子中的碱基发生加成反应，OH·等加到碱基（胸腺嘧啶 C6 或 C5，腺嘌 呤 C8）的双链上，破坏碱基可产生基因突变。 （2）自由基可加成到膜脂及其他脂类不饱和脂肪酸的双链中，引起脂质过氧化，并可产生 新的自由基。如脂质过氧化可使线粒体损伤，导致能量代谢障碍；微粒体损伤，使多聚核糖 体解聚，抑制蛋白质合成；溶酶体损伤可使溶酶体膜通透性改变，使机体受到更大损伤。 （3）自由基常攻击肽链上的脯氨酸残基，引入羰基而生成α-吡咯烷酮，经水解与其相邻氨 基酸断开，造成蛋白质断裂。此外自由基还引起蛋白质交联、蛋白质残基侧链基发生改变、 破坏蛋白质高级结构等。 （4）自由基的氧化损伤涉及到细胞骨架蛋白。如肌动蛋白是构成微丝的主要蛋白质，其 4 个—SH 可成为氧化的对象，肌动蛋白与氧化型谷胱甘肽之间形成二硫键可导致分子表面电 荷的改变；在老化的红细胞中也可检测出类似的修饰物，用醌处理的细胞中也发现不同肌动 蛋白分子或肌动蛋白与其他蛋白质之间形成二硫键，这种氧化性蛋白质交联引起大分子的聚 集。", "kp": "ch12_s1_6"}], "term": [{"id": "ch12_term_8", "modI": 1, "term": "胞质体（cytoplast）。", "def": "胞质体是指除去细胞核后由膜包裹的无核细胞。", "kps": "", "kp": "ch12_s1_7"}, {"id": "ch12_term_10", "modI": 1, "term": "自由基（free radical）。", "def": "自由基是具有高度活性、通常寿命短暂的分子片段具有的一个或多个未配对电子。自由 基的种类很多，活性最强的是氧中心自由基，简称氧自由基，包括 O2（超氧自由基）、·OH （羟自由基）和 H2O2。", "kps": "", "kp": "ch12_s1_4"}]}, {"i": 2, "name": "3.2 线粒体DNA突变", "slides": [{"i": 8, "sec": "3.2 线粒体DNA突变", "title": "3.2 线粒体DNA突变", "notes": "（mitochondrial DNA mutation）\nATP的过程中，大约有1-4%氧转化为氧自由基线粒体是自\n由基浓度很高的细胞器。\n伤害，而催化mtDNA复制的DNA聚合酶不具有校正功能，\n复制错误频率高，同时缺乏有效的修复酶，故mtDNA非\n常容易发生突变。\n如此反复循环。\n而增加，许多研究认为mtDNA缺失与衰老及伴随的老年衰退\n性疾病有密切关系。\n【结合课本/笔记】线粒体（mitochondrion)是细胞内氧化磷酸化和形成 ATP 的主要场所。含丰富的心磷脂和较少的胆固醇是线粒体在组成上与细胞其他膜结构的明显差别。线粒体内、外膜在化学组成上的主要区别是脂类和蛋白质的比例不同， 内膜上的脂类与蛋白质的比值低(0.3:1)， 外膜中的比值较高(接近 1:1)。细胞呼吸：在线粒体内，在 O2 的参与下分解各种大分子物质，产生 CO2；与此同时，分解代谢所释放的能量储存在 ATP 中，这一过程称为细胞呼吸，也称为生物氧化或细胞氧化。呼吸链（电子传递链）：一系列能够可逆地接受和释放 H+和 e-的化学物质所组成的酶体系在线粒体内膜上有序地排列成互相关联的链状氧化磷酸化偶联机制： 化学渗透假说（内膜上的", "page": 9, "level": "掌握", "img": "assets/img/ch12/p009.jpg", "anim": null, "fig": null, "points": ["线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成", "mtDNA裸露于基质，缺乏结合蛋白的保护，最易受自由基", "mtDNA突变使呼吸链功能受损，进一步引起自由基堆积，", "衰老个体细胞中mtDNA缺失表现明显，并随着年龄的增加"], "check": {"q": "关于「线粒体DNA突变」，下列说法正确的是（　）", "o": ["A. 线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成", "B. 变 态：蝌蚪 →→ 青蛙", "C. 自由基：原子核外层轨道上具有不成对电子的分子", "D. 生殖干细胞和癌细胞内端粒酶活性高。"], "a": "A", "e": "本页要点：线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成"}, "cards": null}], "mcq": [], "judge": [], "fill": [], "short": [], "calc": [], "term": []}, {"i": 3, "name": "3.3 “端粒时钟学说/有丝分裂钟”", "slides": [{"i": 9, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "3.3 “端粒时钟学说/有丝分裂钟”", "notes": "（2009 Nobel Prize）\n染色体两个端部特化结构, 富含鸟嘌呤核苷酸(G)\n的短的DNA串联重复序列组成(several thousand copies\nof the telomere sequence)；用以保证染色体的完整性和\n稳定性，不环化、不粘合、不被降解。\n锥虫：TTAGG)\n体复制时由DNA聚合酶连续复制合成的, 而是由端粒酶\n合成后添加到染色体末端的。", "page": 10, "level": "掌握", "img": "assets/img/ch12/p010.jpg", "anim": null, "fig": null, "points": ["端粒(telomere DNA sequence, TEL):", "广泛存在各类真核细胞中, 其保守性是惊人的。(人/", "真核细胞染色体端粒DNA重复序列(TEL)不是染色"], "check": {"q": "关于「“端粒时钟学说/有丝分裂钟”」，下列说法正确的是（　）", "o": ["A. The nematode Caenorhabditis elegans was an ideal model", "B. 端粒(telomere DNA sequence, TEL):", "C. 依赖于凋亡蛋白酶-Caspase的途径", "D. 以上说法均不完全"], "a": "B", "e": "本页要点：端粒(telomere DNA sequence, TEL):"}, "cards": null}, {"i": 10, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "染色体三个功能元件之一：端粒DNA序列(TEL)", "notes": "Despite the evolutionary\ndivergence of eukaryotic\norganisms, the repeated\nsequences of telomeric DNA\nare remarkably conserved.", "page": 11, "level": "掌握", "img": "assets/img/ch12/p011.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 11, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "• 端粒酶(telomerase)：是一种核糖核蛋白复合物(RNA+蛋", "notes": "白质)，具逆转录酶性质，催化合成telomere DNA sequence\n加到染色体末端。\n酶活性很高；\n端粒酶活性，但不足完全弥补\n缩短；\n活性。\n端粒酶的蛋\n白质部分\n端粒酶组分中\n的RNA模板\nStructure of telomerase", "page": 12, "level": "掌握", "img": "assets/img/ch12/p012.jpg", "anim": null, "fig": null, "points": ["生殖干细胞和癌细胞内端粒酶活性高。", "生殖细胞、癌细胞内端粒", "多数单能和多能干细胞有一定", "正常体细胞尚未发现端粒酶"], "check": {"q": "关于「• 端粒酶(telomerase)：是一种核糖核…」，下列说法正确的是（　）", "o": ["A. Nuclear lamina 核纤层蛋白", "B. 细胞衰老(cell senescence, cell aging)", "C. 酶促反应的酶", "D. 生殖干细胞和癌细胞内端粒酶活性高。"], "a": "D", "e": "本页要点：生殖干细胞和癌细胞内端粒酶活性高。"}, "cards": null}, {"i": 12, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "➢ 真核细胞DNA复制过程：", "notes": "末端复制问题，由于DNA\n聚合酶不能从头合成子链，复制\n母链3’端时，子链5’末端RNA引\n物切除后产生末端缺失。子链5’\n末端随着分裂次数的增加逐渐缩\n短(30-120bp/次)。\n➢ 端粒的存在使得染色体5’末端\n的缩短不会影响到编码区。\n➢ 端粒酶：自身RNA模板反转录\n出端粒DNA。\n【结合课本/笔记】核体（nuclear bodies，NBs）核基质(nuclear matrix)核基质或核骨架(nuclear skeleton)的概念狭义概念仅指核基质，即细胞核内除了核被膜、核纤层、染色质与核仁以外的网架结构体系。广义概念应包括核基质、核纤层(或核纤层-核孔复合体结构体系),以及染色体骨架。目前对核骨架的研究结论核骨架是存在于真核细胞核内真实的结构体系；核骨架与核纤层、中间纤维相互连接形成贯穿于核与质的一个独立结构系统。核骨架的主要成分是由非组蛋白的纤维蛋白构成的, 含有多种蛋白成分及少量RNA；核骨架与DNA复制、基因表达及染色体的包装与构建有密切关系。", "page": 13, "level": "掌握", "img": "assets/img/ch12/p013.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 13, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "（本页为图片/无文字层）", "notes": "", "page": 14, "level": "掌握", "img": "assets/img/ch12/p014.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 14, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "（本页为图片/无文字层）", "notes": "", "page": 15, "level": "掌握", "img": "assets/img/ch12/p015.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 15, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "—迄今为止, 只发现生殖细胞/部分干细胞里有较高的", "notes": "telomerase活性，而体细胞中telomerase活性极低，呈\n抑制/失活状态。\n正常情况，由于体细胞端粒酶处于抑制状态，细胞\n分裂时DNA复制不完全而引起端粒DNA少量丢失，\nDNA每复制一次，端粒缩短一段；\n随着细胞分裂次数增加, 端粒不断缩短, 当端粒长度\n缩短到一定阈值时，细胞不再分裂，进入衰老。\nP53识别缩短的端粒(视作DNA损伤)，p21抑制CDK活化，\nRb不被磷酸化，E2F持续失活，细胞不能G1→S，最终引\n发细胞衰老。", "page": 16, "level": "掌握", "img": "assets/img/ch12/p016.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 16, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "端粒缩短是衰老的一个指标", "notes": "◼ 端粒缩短诱导体内细胞变老\n◼ 用限制性内切酶得到的端粒片段由胎儿细胞中的\n12kb下降到年老个体中的7 kb—纤维原细胞。", "page": 17, "level": "掌握", "img": "assets/img/ch12/p017.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 17, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "Part II   细胞凋亡 (apoptosis)", "notes": "生命的自然过程; 由严格的遗传机制决定的程序\n性调控，又称细胞程序性死亡(programmed cell\ndeath, PCD)\n生物生命活动过程中不可缺少的组成内容，是\n生物体为了更好地适应环境而采取的主动死亡\n的过程\n【结合课本/笔记】第二节           细胞凋亡(Apoptosis)●细胞凋亡的概念及其生物学意义", "page": 18, "level": "掌握", "img": "assets/img/ch12/p018.jpg", "anim": null, "fig": null, "points": ["细胞凋亡是一个主动的由基因决定的自动结束", "无论在动物还是植物中，细胞凋亡都是多细胞"], "check": {"q": "关于「Part II 细胞凋亡 (apoptosis)」，下列说法正确的是（　）", "o": ["A. The effector protein in the apoptotic pathway are", "B. 细胞凋亡是一个主动的由基因决定的自动结束", "C. 抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；", "D. 外源途径活化Caspase-8"], "a": "B", "e": "本页要点：细胞凋亡是一个主动的由基因决定的自动结束"}, "cards": null}, {"i": 18, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "细胞凋亡普遍存在", "notes": "昆虫 、卵 → 幼虫 → 成虫\n5% 成熟后只存活一至几天\n如防止免疫过激，诱导T淋巴细胞凋亡来控制其寿命和数量。", "page": 19, "level": "掌握", "img": "assets/img/ch12/p019.jpg", "anim": null, "fig": null, "points": ["变 态：蝌蚪 →→ 青蛙", "哺乳类: 皮肤，指（趾）甲", "淋巴细胞：95% 以上在成熟之前死去，不到", "维持生物体内的自稳态，细胞分裂与凋亡的平衡。", "癌细胞亦可看作是凋亡失控了的细胞"], "check": {"q": "关于「细胞凋亡普遍存在」，下列说法正确的是（　）", "o": ["A. Nuclear lamina 核纤层蛋白", "B. 细胞衰老(cell senescence, cell aging)", "C. 变 态：蝌蚪 →→ 青蛙", "D. 酶促反应的酶"], "a": "C", "e": "本页要点：变 态：蝌蚪 →→ 青蛙"}, "cards": null}, {"i": 19, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "Programmed cell", "notes": "death in the\nembryonic mouse\npaw.\nApoptosis during the metamorphosis of a tadpole into a frog", "page": 20, "level": "掌握", "img": "assets/img/ch12/p020.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 20, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "脊椎动物神经系统发育过程中，只有约50%的原始神经元与靶", "notes": "细胞简历连接，接收到足够量的存货因子-神经生长因子NGF，\n才能生存；没有与靶细胞建立连接的神经元发生凋亡。\n胚胎中产生的神经细胞通常是过量的，然后通过竞争数量有限\n的从靶细胞分泌的生长因子才能生存下来。\n细胞凋亡是神经细胞与靶细胞的数量相匹配，建立正确的神经\n网络。", "page": 21, "level": "掌握", "img": "assets/img/ch12/p021.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 21, "sec": "3.3 “端粒时钟学说/有丝分裂钟”", "title": "This strategy of overproduction followed", "notes": "by culling ensures that all target cells are\ncontacted by nerve cells and that the\nextra nerve cells are automatically\neliminated.", "page": 22, "level": "掌握", "img": "assets/img/ch12/p022.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch12_mcq_8", "mod": "3.3 “端粒时钟学说/有丝分裂钟”", "modI": 3, "q": "下列哪一项不是 P53 的正常功能？（    ）", "o": ["A．激活细胞周期抑制因子的转录", "B．在 Dy4A 修复中起作用", "C．触发损伤细胞的凋亡", "D．在小鼠胚胎发育中起基本作用 【答案】D  【解析】P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。"], "a": "D", "e": "P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。", "kp": "ch12_s3_15"}], "judge": [{"id": "ch12_judge_10", "modI": 3, "q": "蛙发育过程中尾巴的退化涉及细胞的程序性死亡和细胞坏死过程。（                   ）", "a": "错", "e": "蛙发育过程不涉及细胞坏死过程。", "kp": "ch12_s3_17"}, {"id": "ch12_judge_12", "modI": 3, "q": "编程性死亡是导致细胞衰老的一个重要原因。（                     ）", "a": "对", "e": "", "kp": "ch12_s3_16"}], "fill": [{"id": "ch12_fill_1", "modI": 3, "q": "动物细胞程序性死亡的 3 种方式是______、______和______。", "a": "凋亡；坏死；自噬", "kp": "ch12_s3_17"}], "short": [{"id": "ch12_short_2", "modI": 3, "q": "举例说明细胞凋亡的生物学意义。", "a": "（1）保证个体正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控。 （2）是一种生理性保护机制，清除体内多余、受损或危险的细胞而不对周围的细胞或组织 产生损害。如：神经元细胞数量的调节、器官细胞数量的稳定、成体细胞的自然更新以及病 原体感染细胞的清除等。 （3）细胞凋亡的失调导致疾病：细胞凋亡不足，如肿瘤。细胞凋亡过度，导致自身免疫病 和炎症，如败血症、心肌梗塞、艾滋病、老年痴呆、帕金森病。", "kp": "ch12_s3_17"}, {"id": "ch12_short_9", "modI": 3, "q": "简述参与秀丽新小杆线虫的细胞程序性死亡基因的分组及相关作用。", "a": "参与秀丽新小杆线虫的细胞程序性死亡的 15 个基因，根据其作用不同大致可分为四组。 （1）第 1 组含同 PCD 有关的决定死亡的两个基因，即 ces-1（ces 表示 CE 细胞存活的调控 基因）和 ces-2 基因，即该组基因在线虫 CE 的 PCD 调控具有重要意义；（2）第 2 组含有 执行死亡的四个基因：ced-3（cell death）、ced-4、ced-9 和 eg-1 基因；（3）第 3 组含有 7 个与死亡细胞被吞噬细胞所吞噬的基因，即 ced-1、ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；（4）第 4 组是死亡细胞在吞噬体中被降解的基因，如核酸酶基因 l，即 nuc-1 基因， 如果 nuc-1 发生突变，则 DNA 裂解受阻，但不能抑制细胞死亡，表明此核酸酶并非 PCD 所 必需。由这四组基因共同作用导致线虫细胞的程序化死亡。", "kp": "ch12_s3_17"}, {"id": "ch12_short_10", "modI": 3, "q": "如何证明细胞程序死亡受到相关基因的正、负调控？试以线虫为例作简要说明。", "a": "（1）线虫发育过程中有 131 个细胞注定要程序死亡，已经证明有 11 种基因与该程序死 亡有关，其中 3 种与程序死亡的开始有关。（2）其中 ced3 和 ced4 基因是细胞程序死亡所 必需的，在 ced3 和 ced4 突变株中，原来要死亡的细胞可以生存，ced3 和 ced4 属于正调控 基因。（3）ced9 基因对 ced3 和 eed4 行使负调控。因为观察到表达 ced9 的突变株中，上述 细胞不进入程序死亡，而在野生型中这些细胞要凋亡。", "kp": "ch12_s3_17"}], "calc": [{"id": "ch12_calc_3", "modI": 3, "q": "什么是细胞程序性死亡？试述细胞程序化死亡的基因调控机制。", "a": "细胞程序性死亡是细胞按某种预定程序进行的生理性的自然死亡过程，它是有机体生长 发育过程中不可缺少的环节。 （1）死亡受体介导的细胞凋亡：死亡受体属肿瘤坏死因子基因家族，其共同特征都有相似 的、富含半胱氨酸的细胞外结构域。死亡受体还有一个同源的、被称为死亡结构的域的胞内 序列。死亡结构域一般使死亡受体与胞内凋亡机制相连，但有时也会介导与凋亡无关或抑制 凋亡的过程。 （2）线粒体介导的细胞凋亡：在脊椎动物细胞凋亡过程中，线粒体被认为处于凋亡调控的 中心位置。死亡信号诱使线粒体渗透性转换孔开启，导致线粒体跨膜电位的崩解，从而使凋 亡相关活性物质释放，继而对 caspase 酶系激活是细胞凋亡实现的最根本的生物化学途径。 （3）凋亡相关基因：在细胞凋亡的分子生物学研究过程中，发现了有多种基因参与细胞凋 亡的基因调控，其中包括 ced 基因、bel-2 基因、ICE 基因、p53 基因、Fas／Ap0 基因及 c-myc 基因等。随着研究的深入，还发现其他多种可能与凋亡调控有关的基因，只是研究起步较晚， 许多控制机制尚无法阐明。", "kp": "ch12_s3_17"}, {"id": "ch12_calc_6", "modI": 3, "q": "试述细胞凋亡的生物学意义与主要研究方法？ 相关试题：“Life is dependent on the cell death，生命依赖于细胞的死亡”，根据这句听起来似 乎是矛盾的悖论，试回答（1）什么是细胞凋亡？（2）细胞凋亡对生命活动（包括生理和病 理）的意义。", "a": "（1）细胞凋亡的生物学意义 参见 16.2 课后习题详解第 2 题。 （2）细胞凋亡常用的研究方法 ①形态学观察 a．台盼蓝染色法 台盼蓝无法进入活细胞，但可使死细胞着色。 b．4′,6-二脒基-2-苯基吲哚（DAPI）染色法 DAPI 是一种能与 DNA 结合的荧光染料，可以染细胞核，借助荧光显微镜，可以观察到细 胞核的形态变化。 c．吉姆萨（Giemsa）染色法 吉姆萨可以使染色质着色，便于在普通光学显微镜下观察到染色质固缩、趋边化、凋亡小体 的形成等凋亡过程。 ②DNA 电泳 细胞凋亡时，染色质 DNA 在核小体间被特异性切割，降解成 180～200bp 或其整数倍片段， 提取的 DNA 在进行琼脂糖凝胶电泳时，呈现出梯状条带。 ③DNA 断裂的原位末端标记法 凋亡细胞的核 DNA 断裂后产生 3′-OH 末端，可借助一种可观测的标记物如荧光素对单个凋 亡细胞核或凋亡小体进行原位染色，用荧光显微镜进行观察；而正常的或正在增殖的细胞几 乎没有 DNA 的断裂，因而没有 3′-OH 形成，很少能够被染色。 ④彗星电泳法 彗星电泳法是指将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进行短时间的 电泳，并用荧光染料染色来鉴定细胞凋亡的方法。凋亡细胞中的 DNA 降解片段，在电场中 泳动速度较快，使细胞核呈现出一种彗星式的图案，而正常的无 DNA 断裂的核在泳动时保 持圆球形。 ⑤流式细胞分析 凋亡细胞 DNA 发生断裂和丢失，呈亚二倍体状态；采用碘化丙啶染色使 DNA 产生激发荧 光，流式细胞仪能够检测出凋亡的亚二倍体细胞。 ⑥检测细胞膜成分变化 细胞凋亡早期，位于细胞膜内侧的磷脂酰丝氨酸翻转至细胞膜外侧，可以用针对磷脂酰丝氨 酸的荧光标记探针进行检测。 ⑦其他的生理生化方法 检测 caspases 的激活、Cyt c 的释放、线粒体膜电位的变化等。", "kp": "ch12_s3_19"}, {"id": "ch12_calc_10", "modI": 3, "q": "复制衰老的可能机制是什么？", "a": "复制衰老的可能机制是端粒的缩短，即端粒的缩短可以引发细胞的复制衰老。 由于体细胞内缺乏端粒酶活性，随着细胞分裂次数增多，端粒逐渐缩短。端粒的缩短会使细 胞中的 p53 肿瘤抑制因子含量明显增加，继而诱导 p21 的表达，抑制 CDK 的活化，使得 Rb 不能被磷酸化，E2F 处于持续失活状态，细胞不能从 G1 期进入 S 期，最终引发细胞衰老。 具体过程如下： （1）Rb 蛋白能够与转录因子 E2F 家族成员结合并阻止其转录活性，当 E2F 的活性被 Rb 封 闭时，不能正常起始 G1／S 转换过程中若干关键因子的转录，细胞将不进入 S 期而停留在 G1 期。随着细胞周期重要调控因子——CDK 的活化，Rb 被 CDK 磷酸化，磷酸化的 Rb 不 再与 E2F 结合，使得 E2F 被释放并活化靶基因而转录，细胞就从 G1 进入 S 期。 （2）如果 CDK 的正常活化被抑制，或者 Rb 蛋白本身发生突变，导致 Rb 不能被磷酸化， 就会使 G1 期到 S 期的转换被停滞，从而阻断细胞周期的正常运行，引发细胞衰老。", "kp": "ch12_s3_16"}], "term": [{"id": "ch12_term_5", "modI": 3, "term": "端粒（telomere）。", "def": "端粒（telomere）是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。 对染色体结构稳定、末端复制等有重要作用。端粒常在每条染色体末端形成一顶“帽子”结构。", "kps": "", "kp": "ch12_s3_9"}, {"id": "ch12_term_9", "modI": 3, "term": "程序性细胞死亡（programmed cell death）。", "def": "程序性细胞死亡是细胞的一种生理性、主动性的“自杀”现象，是主动由基因决定的细胞 自动结束生命的过程。这些细胞死得有规律，似乎是按编好了的“程序”进行的，是生物体在 漫长进化过程中逐步建立的细胞“自杀”机制，其重要作用是清除多余的、受损的、癌变的或 微生物感染的细胞，维持机体内环境的稳定。程序性细胞死亡的类型有多种，细胞凋亡只是 其中之一。", "kps": "", "kp": "ch12_s3_17"}, {"id": "ch12_term_14", "modI": 3, "term": "细胞凋亡", "def": "细胞凋亡即程序性细胞死亡（PCD），是指细胞在一定的生理或病理条件下，受内在遗 传机制的控制自动结束生命的过程。细胞凋亡是多细胞有机体为调控机体发育，维护内环境 稳定，由基因控制的细胞主动死亡过程。主要形态特征包括细胞核浓缩、染色体 DNA 被以 核小体为单位切成梯状片段、细胞凋亡小体形成等。", "kps": "", "kp": "ch12_s3_17"}]}, {"i": 4, "name": "1.1 细胞凋亡的研究方法", "slides": [{"i": 22, "sec": "1.1 细胞凋亡的研究方法", "title": "1.1 细胞凋亡的研究方法", "notes": "细胞凋亡的检测\nDNA梯状条带(DNA ladder)", "page": 23, "level": "掌握", "img": "assets/img/ch12/p023.jpg", "anim": null, "fig": null, "points": ["形态学观察", "DNA电泳: 发生核小体(180-200bp)间断裂", "DNA断裂的原位末端标记法 TUNEL法"], "check": {"q": "关于「细胞凋亡的研究方法」，下列说法正确的是（　）", "o": ["A. 自由基：原子核外层轨道上具有不成对电子的分子", "B. 生殖干细胞和癌细胞内端粒酶活性高。", "C. 形态学观察", "D. 变 态：蝌蚪 →→ 青蛙"], "a": "C", "e": "本页要点：形态学观察"}, "cards": null}, {"i": 23, "sec": "1.1 细胞凋亡的研究方法", "title": "细胞凋亡与坏死区别-形态学", "notes": "细胞凋亡(apoptosis)   细胞坏死(necrosis)\n细胞膜泡内陷变样但完整         细胞膜失去完整性\n细胞分为一个个凋亡小体         细胞破裂，胞浆外溢\n被周围细胞吞噬，无炎症反应       引起严重的炎症反应\n溶酶体完整               溶酶体破坏，酶漏出\n核染色质凝聚固缩，DNA有控      细胞核弥散性降解\n裂解", "page": 24, "level": "掌握", "img": "assets/img/ch12/p024.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 24, "sec": "1.1 细胞凋亡的研究方法", "title": "Apoptotic cells break apart without spewing forth", "notes": "cell constituents that might harm neighboring cells.\nNormal white blood cell    Cells undergoing apoptosis", "page": 25, "level": "掌握", "img": "assets/img/ch12/p025.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 25, "sec": "1.1 细胞凋亡的研究方法", "title": "细胞坏死与细胞凋亡的形态学特征", "notes": "【结合课本/笔记】●细胞凋亡的分子调控机理一、细胞凋亡的概念及其生物学意义●概念：细胞凋亡是一个主动的由基因决定的自动结束生命的过程，所以也常常被称为细胞编程死亡（programmed cell death,PCD）。凋亡细胞将被吞噬细胞吞噬。●生物学意义：细胞凋亡对于多细胞生物个体发育的正常进行，自稳平衡的保持以及抵御外界各种因素的干扰方面都起着非常关键的作用：蝌蚪尾的消失，骨髓和肠的细胞凋亡，脊椎动物的神经系统的发育，发育过程中手和足的成形过程。二、细胞凋亡的形态学和生物化学特征●细胞凋亡与坏死(necrosis)●细胞凋亡的形态学特征●细胞凋亡的生化特征●诱导细胞凋亡的因子●细胞凋亡的检测细胞凋亡与坏死(necrosis)●二者的主要区别是，细", "page": 26, "level": "掌握", "img": "assets/img/ch12/p026.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 26, "sec": "1.1 细胞凋亡的研究方法", "title": "凋亡小体：凋亡细胞细胞核染色质DNA有控裂解", "notes": "形成核碎片，然后整个细胞通过发芽、起泡等方\n式形成球形突起，并在其基部绞断脱落形成大小\n不等，内含胞质、细胞器及核碎片的小体，称。\n凋亡\n坏死", "page": 27, "level": "掌握", "img": "assets/img/ch12/p027.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 27, "sec": "1.1 细胞凋亡的研究方法", "title": "DNA 电泳特点", "notes": "DNA梯状条带(DNA ladder):凋亡细胞特异性核酸内切\n酶(CAD)有规律切割染色质DNA片段，均发生核小体\n(180-200bp)间断裂，大小为180-200bp倍数。\nCAD: the\nendonuclease\n核酸内切酶\niCAD: its inhibitor", "page": 28, "level": "掌握", "img": "assets/img/ch12/p028.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 28, "sec": "1.1 细胞凋亡的研究方法", "title": "透射电镜显示串珠状", "notes": "11nm的核小体结构", "page": 29, "level": "掌握", "img": "assets/img/ch12/p029.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 29, "sec": "1.1 细胞凋亡的研究方法", "title": "DNA断裂的原位末端标记法", "notes": "TUNEL法\n(凋亡细胞中，染色体\nDNA断裂而产生大量\n的黏性3’-OH端)\nThe TUNEL ( TdT-mediated dUTP\nnick end labeling) technique was used\nto label the cut ends of DNA\nfragments in the nuclei of apoptotic\ncells in a tissue section of a developing\nchick leg bud.\n(Genes Dev. 14:549-558 2000)", "page": 30, "level": "掌握", "img": "assets/img/ch12/p030.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 30, "sec": "1.1 细胞凋亡的研究方法", "title": "The Nobel Prize in Physiology or Medicine 2002", "notes": "\"for their discoveries concerning genetic regulation of\norgan development and programmed cell death\"\nSydney Brenner               H. Robert Horvitz   John E. Sulston\nThe Molecular Sciences       Massachusetts       The Wellcome Trust\nInstitute                    Institute of        Sanger Institute\nBerkeley, CA, USA            Technology (MIT)    Cambridge, United\nborn 1927                    Cambridge, MA,      Kingdom\n(in Union of South Africa)   USA                 Born 1942\nBorn 1947", "page": 31, "level": "掌握", "img": "assets/img/ch12/p031.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 31, "sec": "1.1 细胞凋亡的研究方法", "title": "By using the nematode", "notes": "Caenorhabditis elegans as a\nmodel system, they have\nidentified key genes\nregulating organ\ndevelopment and\nprogrammed cell death.\nThey have also shown that\ncorresponding genes\ncontrolling these processes\nexist in humans.\n秀丽线虫为模式生物，鉴定\n了参与调控程序性死亡的重\n要基因。同时，证明了相对\n应的基因存在于高等生物中，\n包括人类。", "page": 32, "level": "掌握", "img": "assets/img/ch12/p032.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 32, "sec": "1.1 细胞凋亡的研究方法", "title": "mesoderm(指趾间", "notes": "In the human foetus,\nthe interdigital\n中胚层), initially\nformed between\nfingers and toes, is\nremoved by PCD.\nThe intestinal\nlumen (肠腔) and\nother tissues are\nsculpted by PCD.", "page": 33, "level": "掌握", "img": "assets/img/ch12/p033.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 33, "sec": "1.1 细胞凋亡的研究方法", "title": "Sydney Brenner", "notes": "organism to study cell differentiation and organ development.\nThis small worm has a short generation time and is\ntransparent, which made it possible to follow cell division\ndirectly under the microscope.\ncould be induced in the genome of C. elegans by the chemical\ncompound EMS.\nspecific effects on organ development.", "page": 34, "level": "掌握", "img": "assets/img/ch12/p034.jpg", "anim": null, "fig": null, "points": ["The nematode Caenorhabditis elegans was an ideal model", "In 1974, Brenner demonstrated that specific gene mutations", "Different mutations were linked to specific genes and to"], "check": {"q": "关于「Sydney Brenner」，下列说法正确的是（　）", "o": ["A. Somatic Cells(体细胞) Have a Finite", "B. The nematode Caenorhabditis elegans was an ideal model", "C. 线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成", "D. 形态学观察"], "a": "B", "e": "本页要点：The nematode Caenorhabditis elegans was an ideal model"}, "cards": null}, {"i": 34, "sec": "1.1 细胞凋亡的研究方法", "title": "秀丽线虫是研究细胞分化和器官", "notes": "发育的理想的模式生物\n1. 1972年，John Kerr, Andrew Wyllie 提出了\n“Apoptosis”\n2. 只有1毫米长秀丽线虫有1090个细胞 ， 959个体细\n胞，131个细胞凋亡。找到15个与细胞凋亡（PCD）\n有关的基因\n3. 半透明的，可以方便地在显微镜下直接观察细胞\n的分裂。1986年, Robert Horvetz 等发现：ced-3基\n因突变造成原来能自然凋亡的细胞不再凋亡。", "page": 35, "level": "掌握", "img": "assets/img/ch12/p035.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 35, "sec": "1.1 细胞凋亡的研究方法", "title": "（本页为图片/无文字层）", "notes": "", "page": 36, "level": "掌握", "img": "assets/img/ch12/p036.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 36, "sec": "1.1 细胞凋亡的研究方法", "title": "线虫细胞分化谱系示意图", "notes": "", "page": 37, "level": "掌握", "img": "assets/img/ch12/p037.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 37, "sec": "1.1 细胞凋亡的研究方法", "title": "including man. 在秀丽线虫中发现了控制细胞死亡的基", "notes": "Robert Horvitz identified genes controlling cell death\nin C. elegans. Corresponding genes exist in mammals,\n因，其相对应的基因在哺乳动物(包括人类)中也有发现。\n接受信号        编程死亡过程（执行） 吞噬细胞吞噬 彻底降解\n决定死亡\n\"death genes”: ced-3&ced4; ced-9, protects\nagainst cell death by interacting with ced-4 and ced-3.", "page": 38, "level": "掌握", "img": "assets/img/ch12/p038.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 38, "sec": "1.1 细胞凋亡的研究方法", "title": "秀丽隐杆线虫(Caenorbabditis Elegans)与", "notes": "凋亡有关的基因\n 接受信号决定死亡\n 编程死亡（执行过程）\nced-3、ced-4 诱发、启动凋亡\nced-9             抑制凋亡, 存活因子\nCED-3 and CED-4 proteins are required for cell\ndeath, that CED-9 suppresses apoptosis.\n控制相邻细胞吞噬该凋亡细胞\nced-1, ced-2, ced-5, ced-6, ced-7, ced-10 等\n 凋亡细胞被彻底降解：DNA有序裂解 nuc-1", "page": 39, "level": "掌握", "img": "assets/img/ch12/p039.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 39, "sec": "1.1 细胞凋亡的研究方法", "title": "1 一些疾病，比如癌症和某", "notes": "The Implications of the Discoveries\n些自身免疫性疾病，都是\n以细胞凋亡的明显减少为\n主要特征，那些在正常情\n况下应该凋亡的细胞却存\n活下来。\n许多针对癌症的处理策略都\n是建立在刺激细胞“自杀程序”\n的基础上。\n2. 在艾滋病、神经变性疾\n病、中风和心肌梗塞中，\n由于细胞过多死亡而导致\n细胞的缺失。", "page": 40, "level": "掌握", "img": "assets/img/ch12/p040.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch12_mcq_3", "mod": "1.1 细胞凋亡的研究方法", "modI": 4, "q": "细胞凋亡 DNA 双链的断裂的主要部位是（    ）。", "o": ["A．富含 AT 的区域", "B．富含 GC 的区域", "C．核小体之间的连接区", "D．已经发生 DNA 损伤的部位 【答案】C  【解析】细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。"], "a": "C", "e": "细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。", "kp": "ch12_s4_22"}], "judge": [{"id": "ch12_judge_2", "modI": 4, "q": "细胞凋亡与细胞坏死一般都不会引起细胞的炎症反应。（          ）", "a": "错", "e": "细胞凋亡与坏死不同，凋亡过程中内含物不泄出，通常不引起细胞炎症反应。", "kp": "ch12_s4_23"}, {"id": "ch12_judge_3", "modI": 4, "q": "凋亡小体只能被吞噬细胞所吞噬。（         ）", "a": "错", "e": "凋亡小体为邻近的细胞所吞噬，但并非完全为吞噬细胞所吞噬。", "kp": "ch12_s4_26"}, {"id": "ch12_judge_4", "modI": 4, "q": "决定秀丽新小杆线虫细胞自杀性死亡的细胞杀手是基因 cdc-9 而不是基因 cdc-3 和 cdc-4。 （     ）", "a": "错", "e": "杀手基因是基因 ced-3，基因 ced-9 的产物是存活因子。", "kp": "ch12_s4_36"}, {"id": "ch12_judge_5", "modI": 4, "q": "细胞坏死往往会引起炎症，而程序性细胞死亡不会引起炎症，根本原因是细胞是否破裂。 （     ）", "a": "对", "e": "程序性细胞死亡不会导致细胞破裂，因而不会有伤口，也就不会引起感染。", "kp": "ch12_s4_23"}, {"id": "ch12_judge_9", "modI": 4, "q": "凋亡小体中的染色质块外一般包有核膜来源的双层膜结构。（          ）", "a": "错", "e": "凋亡起始时骨架杂乱，细胞间接触消失，细胞间粘附力下降；细胞质和核浓缩，显 微镜下观察可发现细胞膜发泡，染色质凝集，沿着核膜形成新月形帽状结构；随着细胞膜内 折，染色质断裂成片断，染色质片断及线粒体等细胞器反折的细胞膜包围并逐渐分开，形成 单个的凋亡小体。", "kp": "ch12_s4_26"}], "fill": [{"id": "ch12_fill_9", "modI": 4, "q": "______年的诺贝尔生理学和医学奖授予了在器官发育和程序性细胞死亡研究领域中做出 奠基性贡献的三位科学家：英国的 Brenner、Sulston 和美国的 Horvitz。他们创造性地用______ 作为实验模型，实现了对器官发育过程中的______、______的原位观察，完成了______的绘 制，在此基础上发现并研究了调控器官发育______的关键基因。", "a": "2002；线虫；细胞分裂；分化；细胞图谱；程序性细胞死亡", "kp": "ch12_s4_30"}, {"id": "ch12_fill_10", "modI": 4, "q": "秀丽新小杆线虫的细胞程序性死亡涉及的基因大致分为四组：①______基因，如 Ces-1 和 ces-2 基因；②______基因，即 ced-3、ced-4、ced-9 和 egl-1；③______基因，即 ced-1、 ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；④______基因如核酸酶基因 1，即 muc-1 基 因。", "a": "决定死亡的；执行死亡的；死亡细胞被吞噬细胞所吞噬的；死亡细胞在吞噬体中被 降解的", "kp": "ch12_s4_38"}, {"id": "ch12_fill_17", "modI": 4, "q": "根据细胞死亡诱因的不同，将编程性细胞死亡分为：_________和_________。", "a": "细胞凋亡；细胞自噬", "kp": "ch12_s4_37"}], "short": [{"id": "ch12_short_1", "modI": 4, "q": "细胞凋亡的形态学过程。", "a": "凋亡过程在形态上分为 3 个阶段： （1）凋亡的起始。染色质固缩并沿核膜分布，细胞质发生皱缩，细胞表面特化结构消失。 （2）凋亡小体的形成。细胞质膜反折，包围染色质片段和细胞器等，形成芽状突起并逐渐 分隔，形成凋亡小体。 （3）凋亡小体被吞噬。凋亡小体被邻近的细胞或吞噬细胞所吞噬，并被消化后重新利用。 动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发生细胞外 泄漏，不引发机体的炎症反应。", "kp": "ch12_s4_22"}, {"id": "ch12_short_7", "modI": 4, "q": "细胞坏死性死亡有何特点？", "a": "由于某些外界因素造成细胞的急速死亡为坏死性细胞死亡，其特征是细胞膜通透性增加、 细胞外形变得不规则、细胞核及线粒体肿胀、内质网扩散、溶酶体破裂、最终细胞破坏、胞 浆外溢、细胞解体。这种反应常常引起炎症反应。", "kp": "ch12_s4_23"}, {"id": "ch12_short_16", "modI": 4, "q": "对于多细胞生物，细胞凋亡的生理意义何在？", "a": "多细胞生物细胞凋亡的生理意义如下： （1）细胞凋亡对动物个体的正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控，抵御 外界各种因素的干扰等多种生理及病理过程具有重要意义。 （2）细胞凋亡是一种生理性保护机制，能够清除体内多余、受损或危险的细胞而不对周围 的细胞或组织产生损害。 ①成体细胞的自然更新，通过细胞凋亡来完成被病原体感染的细胞的清除； ②各种杀伤细胞对被感染细胞进行攻击并导致其死亡，也是基于细胞的凋亡。 （3）在成熟的动物个体中，机体通过调节细胞凋亡和细胞增殖的速率来维持组织器官细胞 数量的稳定。 （4）动物发育过程中，细胞凋亡是塑造个体及器官形态的机制之一。", "kp": "ch12_s4_25"}], "calc": [], "term": [{"id": "ch12_term_4", "modI": 4, "term": "细胞坏死（necrosis）。", "def": "细胞坏死（necrosis）是细胞“程序性死亡”的另一种形式，具有包括引发炎症反应在内 的重要生理功能。当细胞凋亡不能正常发生而细胞必须死亡时，坏死作为凋亡的“替补”方式 被细胞采用；此外，分裂旺盛细胞的 DNA 被持续损伤，也能引发细胞坏死，推测原因可能 是 RARP 被活化。", "kps": "", "kp": "ch12_s4_23"}, {"id": "ch12_term_13", "modI": 4, "term": "apoptosis body", "def": "apoptosis body 的中文名称是凋亡小体。凋亡小体是指细胞凋亡时，核染色质断裂为大 小不等的片段，与某些细胞器如线粒体等聚集在一起，被反折的细胞膜所包形成的结构。从 外观看，细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡小体。", "kps": "", "kp": "ch12_s4_23"}, {"id": "ch12_term_15", "modI": 4, "term": "细胞自噬", "def": "细胞自噬是指细胞通过溶酶体与双层膜包裹的细胞自身物质融合，从而降解细胞自身物 质的过程。。正常的动物细胞为了维持细胞内环境的动态平衡，需要不断降解功能失常或不 需要的细胞结构，如各种蛋白质、细胞器以及各种胞质组分。通常，寿命较短的蛋白质如调 控蛋白等通过泛素-蛋白酶体系统进行降解；而寿命较长的细胞结构及蛋白质通过细胞自噬 途径，由溶酶体进行降解。细胞自噬的特征是细胞中出现大的双层膜包裹的自噬泡即自噬小 体。", "kps": "", "kp": "ch12_s4_26"}, {"id": "ch12_term_17", "modI": 4, "term": "necrosis", "def": "necrosis 的中文名称是细胞坏死。细胞坏死是区别于细胞凋亡的另一种细胞死亡方式。 当细胞坏死时，细胞质出现空泡，细胞质膜破损，细胞内含物，包括膨大和破碎的细胞器以 及染色质片段释放到胞外，引起周围组织的炎症反应。", "kps": "", "kp": "ch12_s4_23"}]}, {"i": 5, "name": "1.2 The apoptosis in", "slides": [{"i": 40, "sec": "1.2 The apoptosis in", "title": "mammals 哺乳动物细胞凋亡的调控机制", "notes": "1.2 The apoptosis in humans or other\n1.2.1 Caspase (cysteine-containing aspartate\nspecific proteases)\n属于半胱氨酸蛋白酶，相当于线虫中的ced-3，这\n些蛋白酶是引起细胞凋亡的关键酶，一旦被信号途径\n激活，能将细胞内的靶蛋白裂解，使细胞凋亡。\n它们均有以下特点：\n①酶活性依赖于该酶的半胱氨酸残基；\n②总是在靶蛋白/底物的天冬氨酸残基之后切断底物。", "page": 41, "level": "掌握", "img": "assets/img/ch12/p041.jpg", "anim": null, "fig": null, "points": ["依赖于凋亡蛋白酶-Caspase的途径"], "check": {"q": "关于「mammals 哺乳动物细胞凋亡的调控机制」，下列说法正确的是（　）", "o": ["A. 依赖于凋亡蛋白酶-Caspase的途径", "B. Somatic Cells(体细胞) Have a Finite", "C. 线粒体：主要进行有氧呼吸的细胞器，氧化磷酸化生成", "D. 形态学观察"], "a": "A", "e": "本页要点：依赖于凋亡蛋白酶-Caspase的途径"}, "cards": null}, {"i": 41, "sec": "1.2 The apoptosis in", "title": "天冬氨酸特异性半胱氨酸蛋白酶：", "notes": "(cysteine-containing aspartic acid specific proteases)\n各种Caspase都富含半胱氨酸，被激活后能够在靶\n蛋白的特异Asp残基部位进行切割。\nenzymes called caspases in vertebrates, so named\nbecause they\ncontain a key cysteine residue in the catalytic site\n selectively cleave proteins at sites just\nC-terminal to aspartate residues.\n选择性切割少数(1个)位点，从不完全降解该蛋白。", "page": 42, "level": "掌握", "img": "assets/img/ch12/p042.jpg", "anim": null, "fig": null, "points": ["The effector protein in the apoptotic pathway are", "特异地断开靶蛋白的天冬氨酸(Asp)后的肽键; 高度"], "check": {"q": "关于「天冬氨酸特异性半胱氨酸蛋白酶：」，下列说法正确的是（　）", "o": ["A. DNA损伤、大量氧自由基、胞质Ca2+浓度过高", "B. The effector protein in the apoptotic pathway are", "C. 物种寿命与培养细胞(的传代次数)之间存在正相关的关系。", "D. 端粒(telomere DNA sequence, TEL):"], "a": "B", "e": "本页要点：The effector protein in the apoptotic pathway are"}, "cards": null}, {"i": 42, "sec": "1.2 The apoptosis in", "title": "Caspase存在于细胞胞质溶胶(cytosol)中，人类已鉴定了10多", "notes": "种不同的Caspase。\n两大类：1)起始caspases: caspase 2/8外/9内/10/11\n2) 执行caspases: caspase 3/6/7\n通常以无活性的酶原(procaspase)存在，经活化才可执行功能。\nCaspases are synthesized in the cell as inactive precursors and are\nactivated only during singal-induced apoptosis.\nOver a thousand proteins are cleaved by caspases during apoptosis.\nFor example,\nCAD\nproteins(FAK黏着斑激酶)，细胞与细胞外基质或其他细胞脱离。", "page": 43, "level": "掌握", "img": "assets/img/ch12/p043.jpg", "anim": null, "fig": null, "points": ["Nuclear lamina 核纤层蛋白", "DNA-degrading endonuclease inhibitor(iCAD), 活化了核酸酶", "components of the cytoskeleton细胞骨架 and cell-cell adhension"], "check": {"q": "关于「Caspase存在于细胞胞质溶胶(cytosol…」，下列说法正确的是（　）", "o": ["A. 细胞周期负调节因子表达上调或活性增强，如p53、p21、p16。", "B. 细胞凋亡是一个主动的由基因决定的自动结束", "C. Nuclear lamina 核纤层蛋白", "D. 核纤层蛋白，使位于细胞核膜下的核纤层网络"], "a": "C", "e": "本页要点：Nuclear lamina 核纤层蛋白"}, "cards": null}, {"i": 43, "sec": "1.2 The apoptosis in", "title": "✓ Initiator caspases: caspase8(外源", "notes": "Two major classes of apoptotic\ncaspases:\n信号), 9 (内源)\n✓ Executioner caspases: caspase3,6,7", "page": 44, "level": "掌握", "img": "assets/img/ch12/p044.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 44, "sec": "1.2 The apoptosis in", "title": "Figure 18-5b Molecular Biology of the Cell (© Garland Science 2008)", "notes": "【结合课本/笔记】Alberts B et al. Molecuar Biology of the Cell, 3rd ed. New York and London ： GarlandPublishing，Inc. 1994", "page": 45, "level": "掌握", "img": "assets/img/ch12/p045.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}], "mcq": [{"id": "ch12_mcq_12", "mod": "1.2 The apoptosis in", "modI": 5, "q": "在 caspases 家族中，起细胞凋亡执行者作用的是（               ）。", "o": ["A．caspase-1，-4，-11", "B．caspase-2，-8，-9", "C．caspase-3，-6，-7", "D．caspase-3，-5，-10 【答案】B  【解析】凋亡起始者包括 caspase-2，-8，-9，-10，-11；凋亡执行者包括 caspase-3，-6，-7。"], "a": "B", "e": "凋亡起始者包括 caspase-2，-8，-9，-10，-11；凋亡执行者包括 caspase-3，-6，-7。", "kp": "ch12_s5_43"}], "judge": [{"id": "ch12_judge_6", "modI": 5, "q": "最据 caspase 蛋白在细胞程序性死亡中的作用，将它们分为三大类：调节物、衔接物和效 应物。caspase-9 属于调节物。（  ）", "a": "错", "e": "所有的 caspase 都是效应物。", "kp": "ch12_s5_43"}], "fill": [{"id": "ch12_fill_13", "modI": 5, "q": "一般情况下，抑制动物细胞内的 PI3／Tor 信号通路，可诱导细胞发生______。", "a": "自噬", "kp": "ch12_s5_40"}, {"id": "ch12_fill_16", "modI": 5, "q": "线虫中的 ced9 基因的功能是 。", "a": "抑制细胞凋亡", "kp": "ch12_s5_40"}], "short": [{"id": "ch12_short_8", "modI": 5, "q": "酗酒者及肝癌患者的肝细胞都会发生增殖，试阐述其不同的诱发机制。", "a": "（1）酗酒者体内肝细胞增生是由于肝脏负担过重，并被大量应被代谢的酒精所损害， 这就需要更多的肝细胞激活那个通常调节增生的控制机制。如果肝脏没有严重损坏，在酗酒 者停止饮酒后，肝通常会恢复为原来大小。 （2）在肝癌中，突变破坏正常的细胞增殖控制而使细胞不受控制地持续分裂。", "kp": "ch12_s5_42"}], "calc": [], "term": [{"id": "ch12_term_7", "modI": 5, "term": "阻遏（repression）。", "def": "阻遏是指基因的表达在信使 RNA 合成（转录）阶段为特异的调节因子（阻遏物）所抑 制，使细胞内特定的酶或酶系合成率降低的现象。当特定的代谢物质在细胞内的浓度增加时， 阻遏物就被活化，而相应结构基因群（操纵子）的特异物质的产生就受到抑制。", "kps": "", "kp": "ch12_s5_42"}]}, {"i": 6, "name": "1.2.2 The targets of", "slides": [{"i": 45, "sec": "1.2.2 The targets of", "title": "• More than a dozen protein kinases蛋白激酶: 切", "notes": "1.2.2 The targets of caspases\n割多个蛋白激酶，如粘着斑激酶FAK、PKB、PKC\nand Raf1。破坏细胞之间的黏着和联系。\n（对核内膜起支撑作用）解体，核被膜浓缩。\n改变。\n难以保证正确，导致细胞程序性死亡。\n【结合课本/笔记】第二节 细胞通讯与信号传递●细胞通讯与细胞识别●细胞的信号分子与受体●通过细胞内受体介导的信号传递●通过细胞表面受体介导的信号跨膜传递●由细胞表面整合蛋白介导的信号传递●细胞信号传递的基本特征与蛋白激酶的网络整合信息", "page": 46, "level": "掌握", "img": "assets/img/ch12/p046.jpg", "anim": null, "fig": null, "points": ["核纤层蛋白，使位于细胞核膜下的核纤层网络", "Protein of the cytoskeleton被切割后导致细胞形态", "与DNA修复相关的酶类被切割，使合成的DNA", "水解一个DNase的抑制蛋白，将DNase 激活。"], "check": {"q": "关于「• More than a dozen prot…」，下列说法正确的是（　）", "o": ["A. 抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；", "B. 核纤层蛋白，使位于细胞核膜下的核纤层网络", "C. 外源途径活化Caspase-8", "D. The effector protein in the apoptotic pathway are"], "a": "B", "e": "本页要点：核纤层蛋白，使位于细胞核膜下的核纤层网络"}, "cards": null}], "mcq": [], "judge": [{"id": "ch12_judge_7", "modI": 6, "q": "程序性死亡的细胞之所以能够被吞噬细胞识别和吞噬，是因为这些细胞的表面具有被吞 噬的信号，目前研究得最清楚的被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂 酰乙醇胺分子。（         ）", "a": "错", "e": "被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂酰丝氨酸。", "kp": "ch12_s6_45"}], "fill": [], "short": [{"id": "ch12_short_11", "modI": 6, "q": "根据图 16-1 分析比较线虫与脊椎动物细胞程序化死亡相关的基因及其调节。 图 16-1", "a": "（1）线虫和脊椎动物细胞程序性死亡过程的相似点 在线虫和脊椎动物的细胞程序性死亡调节过程中，都有调节子、接合子、效应子三类分子， 且存在一一对应的同源性基因。调节子抑制接合子的活性，使细胞程序性死亡处于关闭状态。 当细胞程序性死亡受激活信号打开之后，调节子对接合子的抑制作用解除，接合子激活下游 的效应分子，这些效应分子最终导致细胞程序性死亡。 （2）线虫和脊椎动物细胞程序性死亡过程的不同点 脊椎动物的细胞程序性死亡过程中，在接合子的激活下效应子 caspase-9 并不直接导致细胞 的程序性死亡，而是通过激活下游 caspase-3，接着 caspase-3 诱导细胞的程序性死亡。整个 过程较线虫复杂。", "kp": "ch12_s6_45"}, {"id": "ch12_short_12", "modI": 6, "q": "简述 caspases 导致细胞凋亡的机制和 caspases 活化的基本途径。 相关试题：试述细胞程序性死亡的基因调控机制。", "a": "（1）caspases 导致细胞凋亡的机制 ①外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启凋亡反应。 ②内源途径 线粒体接收到凋亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞凋亡。 ③外、内源途径的关联 a．外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可 以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径； b．凋亡的内源途径被激活后，线粒体上释放的促凋亡因子 Smac 也能够活化 caspase-8。 （2）caspases 活化途径 ①经细胞表面受体活化 caspase-2、-8、-10，通过这几个再活化 caspase-3、-7 等凋亡执行因 子，启动凋亡过程。 ②经线粒体中的细胞色素 c 激活 caspase-9，再由 caspase-9 激活下游凋亡执行因子，启动细 胞凋亡。", "kp": "ch12_s6_45"}], "calc": [], "term": []}, {"i": 7, "name": "1.2.3 哺乳动物细胞凋亡的", "slides": [{"i": 46, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "1.2.3 哺乳动物细胞凋亡的", "notes": "分子机理\n◼   依赖于Caspase的途径:\nProcaspase activation can be triggered from either\noutside the cell by the activation of death receptor\non the cell surface (extracellular)\n凋亡细胞外源信号(死亡受体介导) caspase 8\nOr intracellular stimuli\n凋亡细胞内源信号(线粒体Cyt c)介导\ncaspase 9", "page": 47, "level": "掌握", "img": "assets/img/ch12/p047.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 47, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "The two", "notes": "main\nclasses of\nimmune\nresponses.", "page": 48, "level": "掌握", "img": "assets/img/ch12/p048.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 48, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "外源信号介导的凋亡途径起始（Initiation）", "notes": "➢ 信号：肿瘤坏死因子TNF (tumor necrosis factor) :由免疫系\n统细胞合成的能杀死肿瘤，激发细胞凋亡的因子。eg. Fas\nligand，TNF，TRAIL\n➢ 死亡受体(death receptor) : 3个亚基组成的跨膜蛋白，每个亚\n基含有一段死亡结构域(death domain).如TNF-R,Fas等\n➢ 接头蛋白(adaptor protein)-TRADD, FADD:\n以相同的death domain, 与受体TNFR death domains结合 。\nTRADD (TNF receptor associated death domain protein);\nFADD ( Fas-associated death domain)\n➢ procaspase 8caspase8caspase-3\n如分泌Fas ligand的杀伤性T淋巴细胞可以诱导被感染的靶细\n胞凋亡；被损伤的细胞也可自己产生Fas ligand和Fas，触发\n自身凋亡。", "page": 49, "level": "掌握", "img": "assets/img/ch12/p049.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 49, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "杀伤性T- 淋巴细胞使被感染细胞发生凋亡", "notes": "The extrinsic pathway of apoptosis activated through Fas death\nreceptors. Fas ligand on the surface of a killer lymphocyte\nactivates Fas receptors on the surface of the target cell.\nDISC: Death-inducing\nsignaling complex", "page": 50, "level": "掌握", "img": "assets/img/ch12/p050.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 50, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "杀伤性T淋巴细胞", "notes": "被病原体感染的细胞(凋亡细胞)", "page": 51, "level": "掌握", "img": "assets/img/ch12/p051.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 51, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "内源信号介导的细胞凋亡", "notes": "The intrinsic pathway of apoptosis\n等信号能引起线粒体细胞色素c释放到胞质中，\nin normal healthy cells, cytochrome c is localized\nbetween the inner and outer imtochondrial membrane,\nbut in cells undergoing apoptosis, cytochrome c is\nreleased into the cytosol\ncaspase-9前体等形成凋亡小体，然后召集并激活\ncaspase-3，进而引发caspases级联反应，导致细胞凋\n亡。", "page": 52, "level": "掌握", "img": "assets/img/ch12/p052.jpg", "anim": null, "fig": null, "points": ["DNA损伤、大量氧自由基、胞质Ca2+浓度过高", "作为凋亡诱导因子，细胞色素c能与Apaf-1、"], "check": {"q": "关于「内源信号介导的细胞凋亡」，下列说法正确的是（　）", "o": ["A. The nematode Caenorhabditis elegans was an ideal model", "B. 依赖于凋亡蛋白酶-Caspase的途径", "C. 以上说法均不完全", "D. DNA损伤、大量氧自由基、胞质Ca2+浓度过高"], "a": "D", "e": "本页要点：DNA损伤、大量氧自由基、胞质Ca2+浓度过高"}, "cards": null}, {"i": 52, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "B: cells were irradiated", "notes": "with UV light to induce\napoptosis, after 5h, the six\ncells in the bottom half of\nthe picture in B have\nreleasedm cytochroe c\nfrom Mito. into the cytosol.\n(Nat. Cell Biol. 2:156-162 2000)", "page": 53, "level": "掌握", "img": "assets/img/ch12/p053.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 53, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "在这里，一个核心的问题是细胞色素c究竟", "notes": "通过哪一种途径释放到细胞质中?\nThe intrinsic pathway of apoptosis is regulated\nby members of the Bcl-2 family of proteins.\nBcl2 family: family of intracellular proteins that either\npromote or inhibit apoptosis by regulating the release of\ncytochrome c and other mitochondrial proteins from the\nintermembrane space into the cytosol.\n家族成员大多定位于线粒体外膜上，或接收信号后转\n移到外膜上(Bax/Bak)", "page": 54, "level": "掌握", "img": "assets/img/ch12/p054.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 54, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "was first isolated from human follicular lymphomas(滤泡性淋巴", "notes": "Bcl-2, the first mammalian anti-apoptotic gene to be cloned,\n瘤). ⎯ 哺乳动物细胞中抑制凋亡基因，功能相当于线\n虫中的ced-9。在线粒体参与的凋亡途径中起调控作用，\n能控制线粒体中细胞色素c等凋亡因子的释放。\nBcl-2 itself was originally identified as a tumor-\ncausing oncogene, which promoting survival of\npotential cancer cells that would otherwise die.\n(the human Bcl-2 protein and worm CED-9 protein are\nhomologous. And a bcl-2 transgene can block the extensive cell\ndeath found in ced-9 mutant worms, even through the two\nproteins are only 23% homologous.)", "page": 55, "level": "掌握", "img": "assets/img/ch12/p055.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 55, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "根据功能和结构可将Bcl-2家族分为两类，大多数定位于线粒体", "notes": "外膜上，或受信号激活后转移到线粒体外膜。\nanti-apoptotic Bcl-2 family proteins of the outer\nmitochondrial membrane线粒体外膜 that bind and inhibit pro-\napoptotic ones and prevent inappropriate activation of the\nintrinsic pathway of apoptosis.\nIn mammlian cells, Bax and Bak are the main BH123\nproteins, at least one of them is required for the intrinsic\npathway of apoptosis.\nBax is mainly located in the cytosol胞质 and translocates to\nthe mitochondria only after an apoptotic signal activates it.", "page": 56, "level": "掌握", "img": "assets/img/ch12/p056.jpg", "anim": null, "fig": null, "points": ["抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；", "促进凋亡的(pro-apoptotic)，如：Bax、Bak 、Bad;"], "check": {"q": "关于「根据功能和结构可将Bcl-2家族分为两类，大多数…」，下列说法正确的是（　）", "o": ["A. 物种寿命与培养细胞(的传代次数)之间存在正相关的关系。", "B. 端粒(telomere DNA sequence, TEL):", "C. DNA损伤、大量氧自由基、胞质Ca2+浓度过高", "D. 抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；"], "a": "D", "e": "本页要点：抗凋亡的(anti-apoptotic)，如：Bcl-2、Bcl-xl；"}, "cards": null}, {"i": 56, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "凋亡蛋白 — Bcl-2 家族", "notes": "Bid、Bim\n促凋亡因子Bax/Bak寡聚化，从胞质转移至线粒体外膜，作用\n于特定阴离子通道上，使通道开放，Cyt c释放。\nBcl-2/Bcl-x 与前者形成异二聚体，抑制Bax和Bak的寡聚化，\n抑制线粒体膜上的通道开放。", "page": 57, "level": "掌握", "img": "assets/img/ch12/p057.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 57, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "凋亡信号感受器", "notes": "3 classes of Bcl2 proteins\nThe BH3 domain is the only BH domain shared by all bcl2\nfamily members; it mediates the direct interactions between pro-\napoptotic and anti-apoptotic family members.", "page": 58, "level": "掌握", "img": "assets/img/ch12/p058.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 58, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "Bcl2/BclXL", "notes": "Bax/Bak\nBid\nBax/Bak", "page": 59, "level": "掌握", "img": "assets/img/ch12/p059.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 59, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "Apaf 被称为凋亡蛋白酶激活因子 (apoptotic", "notes": "protease activating factor)：\n线虫中的同源物为ced-4，在线粒体参与的凋\n亡途径中具有重要作用。该基因敲除后，小鼠\n神经细胞过多，脑畸形发育\n细胞色素C\n凋亡蛋白酶激活因子Apaf\nCaspase 9酶原\ncaspase 9同源活化\n进一步切割激活caspase 3 &caspase-7", "page": 60, "level": "掌握", "img": "assets/img/ch12/p060.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 60, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "（本页为图片/无文字层）", "notes": "", "page": 61, "level": "掌握", "img": "assets/img/ch12/p061.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 61, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "内源信号介导的凋亡", "notes": "➢ 常态下，Bcl2与Bax/Bad 结合，阻碍后者的寡聚化\n➢ Bid蛋白活化，解除了Bcl2对Bax/Bak的抑制\nBax/Bak发生寡聚化从胞质转移到线粒体膜，与膜上特定阴离\n子通道作用，通道开放(线粒体外膜通透性改变)\ncyto C 从凋亡的线粒体释放到胞质，与Apaf、前体caspase 9形\n成复合物\n激活caspase 9，引发caspase级联反应(caspase-3)，使细胞发生\n凋亡。", "page": 62, "level": "掌握", "img": "assets/img/ch12/p062.jpg", "anim": null, "fig": null, "points": null, "check": null, "cards": null}, {"i": 62, "sec": "1.2.3 哺乳动物细胞凋亡的", "title": "细胞凋亡的内、外源途径", "notes": "彼此关联。\n后，能切割BH3亚家族\n的Bid使其活化。\n膜，解除Bcl-2抑制，\nBax/Bak形成寡聚体，启\n动内源途径。", "page": 63, "level": "掌握", "img": "assets/img/ch12/p063.jpg", "anim": null, "fig": null, "points": ["外源途径活化Caspase-8", "Bid从胞质转移到线粒体"], "check": {"q": "关于「细胞凋亡的内、外源途径」，下列说法正确的是（　）", "o": ["A. 端粒(telomere DNA sequence, TEL):", "B. DNA损伤、大量氧自由基、胞质Ca2+浓度过高", "C. 外源途径活化Caspase-8", "D. 物种寿命与培养细胞(的传代次数)之间存在正相关的关系。"], "a": "C", "e": "本页要点：外源途径活化Caspase-8"}, "cards": null}], "mcq": [{"id": "ch12_mcq_1", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "有关动物细胞凋亡最重要的特征，下列说法错误的是（        ）。", "o": ["A．整个过程中细胞质膜始终保持完整", "B．细胞内含物不发生细胞外泄漏", "C．不引发机体的炎症反应", "D．细胞表面的特化结构消失 【答案】D  【解析】动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。"], "a": "D", "e": "动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_2", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "细胞凋亡的一个重要特点是（     ）。", "o": ["A．DNA 随机断裂", "B．DNA 发生核小体间的断裂", "C．70S 核糖体中的 rRNA 断裂", "D．80S 核糖体中 rRNA 断裂 【答案】B  【解析】凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。"], "a": "B", "e": "凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_10", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "细胞凋亡和细胞坏死过程中都发生的现象是(                   )。", "o": ["A．保持细胞膜的完整性", "B．释放细胞内含物到胞外", "C．基因组 DNA 的降解", "D．引起周围组织的炎症反应 【答案】C  【解析】细胞凋亡过程中，细胞质膜反折，包裹断裂的染色质片段或细胞器，然后逐渐分离， 形成众多的凋亡小体，凋亡小体则被邻近的细胞所吞噬。整个过程中，细胞质膜的完整性保 持良好，死亡细胞的内容物不会逸散到胞外环境中去，因而不引发炎症反应。在细胞坏死时， 细胞质膜发生渗漏，细胞内容物，包括膨大和破碎的细胞器以及染色质片段，释放到胞外， 导致炎症反应。凋亡通常是生理性变化，而细胞坏死则是病理性变化。"], "a": "C", "e": "细胞凋亡过程中，细胞质膜反折，包裹断裂的染色质片段或细胞器，然后逐渐分离， 形成众多的凋亡小体，凋亡小体则被邻近的细胞所吞噬。整个过程中，细胞质膜的完整性保 持良好，死亡细胞的内容物不会逸散到胞外环境中去，因而不引发炎症反应。在细胞坏死时， 细胞质膜发生渗漏，细胞内容物，包括膨大和破碎的细胞器以及染色质片段，释放到胞外， 导致炎症反应。凋亡通常是生理性变化，而细胞坏死则是病理性变化。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_11", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "下列分子哪些与细胞凋亡有关?（                 ）。", "o": ["A．磷脂酰丝氨酸", "B．磷脂酰乙醇胺", "C．磷脂酰胆碱", "D．磷脂酰肌醇 【答案】A  【解析】当细胞凋亡时，膜内侧磷脂酰丝氨酸外翻到膜表面，胞膜结构仍然完整，最终可将 凋亡细胞遗骸分割包裹为几个凋亡小体，无含容物外溢，因此不引起周围的炎症反应，凋亡 小体可迅速被周围专职或非专职吞噬细胞吞噬。"], "a": "A", "e": "当细胞凋亡时，膜内侧磷脂酰丝氨酸外翻到膜表面，胞膜结构仍然完整，最终可将 凋亡细胞遗骸分割包裹为几个凋亡小体，无含容物外溢，因此不引起周围的炎症反应，凋亡 小体可迅速被周围专职或非专职吞噬细胞吞噬。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_14", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "下列关于细胞凋亡说法中，哪项不正确？（               ）", "o": ["A．细胞凋亡是一种正常的生理现象", "B．细胞凋亡受多种因素影响", "C．细胞凋亡过程是受调控的过程", "D．细胞凋亡的形态学特征是细胞结构的全面溶解 【答案】D  【解析】细胞凋亡最重要的特征是整个过程中细胞膜始终保持完整，细胞内含物不泄漏到细 胞外。"], "a": "D", "e": "细胞凋亡最重要的特征是整个过程中细胞膜始终保持完整，细胞内含物不泄漏到细 胞外。", "kp": "ch12_s7_50"}], "judge": [{"id": "ch12_judge_11", "modI": 7, "q": "Caspase 在介导细胞凋亡的过程中，几乎从不完全降解一种蛋白质。                 （  ）", "a": "对", "e": "", "kp": "ch12_s7_62"}], "fill": [{"id": "ch12_fill_2", "modI": 7, "q": "Bcl-2 是一种______（原癌／抑癌）基因，p53 是______基因。", "a": "原癌；抑癌", "kp": "ch12_s7_58"}, {"id": "ch12_fill_3", "modI": 7, "q": "细胞凋亡检测的方法有______、______、______、______和______。", "a": "形态学检测；DNA 电泳；TUNEL 测定法；彗星电泳法；流式细胞分析法", "kp": "ch12_s7_50"}, {"id": "ch12_fill_6", "modI": 7, "q": "细胞死亡有两种形式；一种为______死亡，另一种为______死亡。前者是受到______而 造成的细胞崩溃裂解；后者是细胞在一定的______或______条件下按照自身的程序结束其生 存。", "a": "坏死性；程序性；侵袭；生理；病理", "kp": "ch12_s7_50"}, {"id": "ch12_fill_7", "modI": 7, "q": "从细胞的寿命看，胃壁细胞属于______的细胞，而角膜上皮细胞属于______的细胞。", "a": "更新缓慢；快速更新", "kp": "ch12_s7_50"}, {"id": "ch12_fill_12", "modI": 7, "q": "诱导细胞凋亡的因子可以分为______和______两大类。", "a": "物理性因子；化学及生物因子", "kp": "ch12_s7_50"}, {"id": "ch12_fill_15", "modI": 7, "q": "年轻的功能健全的细胞的膜相是典型的______相。衰老的或者是缺陷的膜通常处于 ______相或______相。", "a": "液晶；凝胶；固相", "kp": "ch12_s7_50"}, {"id": "ch12_fill_18", "modI": 7, "q": "肿瘤坏死因子 TNF 消除肿瘤细胞的机制是通过______。", "a": "caspases 依赖性细胞凋亡途径", "kp": "ch12_s7_48"}], "short": [{"id": "ch12_short_13", "modI": 7, "q": "在活化的细胞毒性 T 淋巴细胞中存在一种称为“粒酶”（granzyme）的丝氨酸蛋白酶，它 同样具有天冬氨酸特异性，能使具有毒性的细胞诱发其靶细胞凋亡，请详细谈一谈“粒酶” 是如何使癌化的细胞或病毒感染的细胞发生凋亡的。", "a": "“粒酶”使癌化的细胞或病毒感染的细胞发生凋亡的过程如下： （1）在靶细胞外，粒酶 B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离。 （2）粒酶 B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白。进入靶细胞后，粒酶 B 通过 caspases 依赖性和 caspases 非依赖性途径促进细胞凋亡。粒酶 B 切割并活化促凋亡因子 Bid， 活化的 Bid 转移到线粒体外膜，改变其通透性，释放 Cyt c 等促凋亡因子，引发 caspases 级 联反应，诱导细胞凋亡。 （3）粒酶 B 还可通过切割凋亡抑制因子 Mcl-1 诱发细胞凋亡内源性途径。", "kp": "ch12_s7_50"}, {"id": "ch12_short_14", "modI": 7, "q": "简述当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径。", "a": "当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径如下： （1）引起细胞凋亡的胞内信号 DNA 损伤、细胞质中 Ca2 浓度过高、极度氧胁迫产生大量自由基等。内源信号中也有抑制 ＋   细胞死亡的负控制信号，如哺乳动物中的 Bcl-2 和 Bcl-X 蛋白。 （2）Bcl-2 蛋白家族对于细胞凋亡的影响 其中有些成员促进凋亡，如 Bad、Bid、Bax；有些成员抑制凋亡，如 Bcl-2、Bcl-XL、BCl-w。 Bcl-2 蛋白定位于线粒体外膜，有双重功能：一是阻止 Cyt c 从线粒体中释放，二是与 Apaf-1 结合。 （3）依赖于线粒体的细胞凋亡途径 当细胞受到损伤或发生应激反应时，激活了 Bcl 家族中的促凋亡蛋白（如 Bad、Bax），这 些蛋白从细胞质转移到线粒体外膜并插入外膜，导致线粒体外膜的通透性发生改变，然后 Cyt c 从线粒体释放到细胞质，进入胞质的 Cyt c 与 Apaf-1、carpase-9 前体等装配成多亚基 蛋白复合体，caspase-9 在凋亡复合体中发生自身切割而活化，激活的 caspase-9 作为起始 caspases 激活下游的执行 caspases，然后执行 caspases 作用于靶蛋白引发细胞程序性死亡， 即细胞凋亡。", "kp": "ch12_s7_50"}], "calc": [{"id": "ch12_calc_5", "modI": 7, "q": "何为细胞程序性死亡？有何特征？发生机制如何？ 相关试题：简述细胞凋亡的概念及凋亡细胞的主要变化。", "a": "（1）细胞程序性死亡的概念 细胞程序性死亡是指在发育过程中发生的某类细胞的大量死亡，而这种细胞死亡要求特定的 基因表达。细胞程序性死亡是一个主动的自我调控的过程，其细胞死亡往往受到细胞内某种 由遗传机制决定的“死亡程序”控制。 （2）细胞程序性死亡的特征 ①细胞核：核凝集，核膜皱缩破裂；染色质致密并沿核膜分布；DNA 降解成片段，出现阶 梯状电泳条带。 ②细胞质：浓缩，细胞骨架解体。 ③细胞膜：细胞连接破坏，细胞膜反折包围染色质片段和细胞器内陷成凋亡小体。 （3）细胞程序性死亡的发生机制 死亡信号→激活死亡信号受体→细胞外信号转变成细胞内信号→蛋白酶家族级联反应→底 物蛋白被水解→细胞凋亡发生。分为 caspases 依赖性的细胞程序性死亡和 caspases 非依赖性 的细胞程序性死亡。 ①caspases 依赖性的细胞程序性死亡 a．外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启程序性死亡反应。外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径。 b．内源途径 线粒体接收到死亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞程序性死亡。 ②caspases 非依赖性的细胞程序性死亡 a．凋亡诱导因子（AIF）是诱导 caspases 非依赖性细胞凋亡的蛋白，位于线粒体外膜，在凋 亡过程中，AIF 从线粒体释放进入细胞核，引起核内 DNA 凝集并断裂形成约 5×104 大小的 片段。 b．限制性内切核酸酶 G 属于 Mg2 依赖性的核酸酶家族，受到凋亡信号的刺激后，限制性 ＋   内切核酸酶 G 从线粒体中释放出来进入细胞核，对核 DNA 进行切割，产生典型的以核小体 为单位的 DNA 片段。 c．磷脂酰丝氨酸等信号分子可以启动凋亡细胞的清除过程。", "kp": "ch12_s7_50"}, {"id": "ch12_calc_7", "modI": 7, "q": "试述细胞凋亡的概念与形态特征，并指出其与坏死的区别是什么？", "a": "（1）细胞凋亡的概念 细胞凋亡是指为维持内环境稳定，由基因控制的细胞自主的有序的死亡。细胞凋亡是主动过 程，涉及一系列基因的激活、表达以及调控等作用，它并不是病理条件下自体损伤的一种现 象，而是为更好地适应生存环境而主动争取的一种死亡过程，最终被吞噬细胞吞噬。细胞凋 亡时在细胞、亚细胞和分子水平上发生了特征性改变。这些改变包括细胞核的改变、细胞器 的改变、细胞膜成分的改变和细胞形态的改变等，其中细胞核的改变最具特征性。 （2）细胞凋亡的形态特征 ①形态学变化 a．凋亡的起始：细胞表面特化结构消失，细胞体积缩小，细胞间接触消失，与周围的细胞 脱离；细胞质密度增加，核质浓缩，核膜、核仁破碎，胞膜有小泡形成，细胞膜结构仍然完 整。 b．凋亡小体的形成：细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡 小体，细胞内含物不泄漏到细胞外。 c．吞噬：凋亡小体可迅速被周围专职或非专职吞噬细胞吞噬，在溶酶体内被消化分解。 ②细胞凋亡的生物化学变化 DNA 发生有控降解，片段化的 DNA 片段为 180～200bp 的整倍数；在细胞凋亡的过程中， 常有新基因的表达和某些生物大分子的合成作为调控因子。 （3）细胞凋亡与细胞坏死的区别 细胞凋亡与细胞坏死的区别如表 16-1 所示： 表 16-1 细胞凋亡与细胞坏死的区别 区 细胞凋亡            细胞坏死 别 是 否 由 基是                    否 因 决 定 诱 导                     剧烈损伤或严重的 生理或轻微病理性刺激 因                     病理性刺激 素 形 细胞膜及细胞器相对完整，细胞皱细胞结构全面溶 态 缩，核固缩，有凋亡小体形成，体解、破坏，细胞肿 特 积缩小                 胀，体积膨大 征 生 化DNA 片段化（180～200bp），电泳随机降解，电泳呈 特呈梯状条带                弥散性分布 点 是 否 引 溶酶体破裂，释放 起溶酶体相对完整，不释放内含物， 内含物，局部有炎 炎局部无炎症反应 症反应 症 反 应 染 凝集，形成新月形帽状结构，沿着 色                     不凝集 核膜分布 质", "kp": "ch12_s7_50"}, {"id": "ch12_calc_8", "modI": 7, "q": "动物细胞凋亡的基本途径有哪些？请举例说明。", "a": "动物细胞凋亡的基本途径主要有： （1）caspases 依赖性的细胞凋亡 ①死亡受体介导的细胞凋亡途径 起始于死亡配体与受体的结合，死亡配体主要是肿瘤坏死因子（TNF)家族成员。当细胞接 受凋亡信号分子（FasL、TNF 等）后，凋亡细胞表面信号分子受体相互聚集并与细胞内的 接头蛋白结合，这些接头蛋白又募集 procaspase 聚集在受体部位，procaspase 相互活化并产 生级联反应，使细胞凋亡。 ②线粒体介导的细胞凋亡途径 在这个凋亡途径中细胞色素 c 的释放是关键步骤。当 caspase-8 活化后，它一方面作用于 caspase-3，另一方面使 Bid 裂解成 2 个片段，其中含有 BH3 结构域的 C 端片段被运送到线 粒体，与 Bcl-2／Bax 的 BH3 结构域形成复合物，导致 Cyt c 释放。Cyt c 与 Apaf-1 结合并 活化 Apaf-1，活化的 Apaf-1 再活化 caspase-9，最后引起细胞凋亡。 （2）caspases 非依赖性的细胞凋亡 相对于 caspases 依赖性的细胞凋亡，caspase 非依赖性的细胞凋亡的机制还不完全清楚。已 知线粒体在 caspase 非依赖性的细胞凋亡过程中同样发挥了关键作用。除了细胞色素 c，线 粒体能够向细胞质内释放多个凋亡因子，引发 caspase 非依赖性的细胞凋亡。如凋亡诱导因 子（AIF）和限制性内切核酸酶 G。 （3）穿孔蛋白-颗粒酶介导的细胞凋亡 ①在靶细胞外，颗粒酶 A、B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离； ②颗粒酶 A、B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白，通过 caspases 依赖性和非依 赖性两种方式促使靶细胞凋亡，其中颗粒酶 A 主要通过 caspases 非依赖性细胞凋亡途径； ③颗粒酶 A 通过切割核纤层蛋白和组蛋白破坏细胞核与染色体结构的稳定性，更有利于 DNA 酶的作用。", "kp": "ch12_s7_50"}, {"id": "ch12_calc_9", "modI": 7, "q": "细胞凋亡受到哪些因素的调控？", "a": "细胞凋亡是一个非常复杂的过程，受到机体内、外多种因素的影响，其调控因素分为诱 导性因素和抑制性因素两大类。 （1）诱导性因素 ①生理性诱导因子 肿瘤坏死因子（TNF）及其家族中 Fas 配体（FasL）、转化生长因子β（TGF-β）、神经递质 （谷氨酸，多巴胺，N-甲酰-D-天门冬氨酸）、Ca2 、糖皮质激素等。 ＋   ②理化因素 射线、高温、强酸、强碱、乙醇、抗癌药物等，均可导致细胞凋亡。例如，电离辐射可产生 大量氧自由基，使细胞处于氧化应激状态，DNA 受损，引起细胞凋亡。 ③免疫性因素 在生长、分化及执行防御、自稳、监视功能中，免疫细胞可释放某些分子导致免疫细胞本身 或靶细胞的凋亡。例如，细胞毒性 T 淋巴细胞可分泌颗粒酶，引起靶细胞的凋亡。 ④微生物学因素 细菌、病毒等致病微生物及其毒素可诱导细胞凋亡。如 HIV 感染时，可致大量 CD4 T 淋巴 ＋   细胞凋亡。 ⑤其他因素 热休克、原癌基因（如 myc，rel，腺病毒 E1A 等）、抑癌基因（如野生型 p53 基因）、缺 血、缺氧等。 （2）抑制性因素 ①生理性抑制因子 bcl-2 原癌基因、突变型 p53、各种生长因子、细胞外基质、CD40 配体、一些中性氨基酸、 锌以及雌、雄激素。例如在培养体系中加入所需要的细胞因子，可促进细胞内存活基因的表 达，抑制细胞凋亡的发生。 ②病毒基因 如腺病毒 E1B、杆状病毒、牛痘病毒 crmA、EB 病毒 BHRF1 及 LMP-1、单纯疱疹病毒等基 因。 ③其他因素 线虫的 ced-9 基因、半胱氨酸蛋白酶抑制剂、钙蛋白酶抑制因子、促癌剂（如 PMA 等）。", "kp": "ch12_s7_50"}], "term": [{"id": "ch12_term_2", "modI": 7, "term": "亡复合体（apotosome）。", "def": "凋亡复合体（apotosome）是指凋亡分子 Apaf-1 与细胞色素 c 形成的复合体，相对分子 量为（700～1400）×103，细胞质中 Caspase-9 的前体被募集到复合体上并发生自动切割活化， 引起细胞凋亡。", "kps": "", "kp": "ch12_s7_51"}, {"id": "ch12_term_3", "modI": 7, "term": "aspase 募集结构域（Caspase recruitment domain，CARD）。", "def": "存在于凋亡起始 Caspase-2 和-9，以及凋亡相关接头蛋白分子中，通过结构域之间的聚 合，Caspase 能够彼此结合或与接头蛋白结合，被募集到上游信号复合物中活化。", "kps": "", "kp": "ch12_s7_48"}, {"id": "ch12_term_11", "modI": 7, "term": "肿瘤坏死因子（tumor necrosis factor，TNF）。", "def": "肿瘤坏死因子是在体内和体外实验中杀死肿瘤，或抑制组织癌变的因子。人的 TNF 有 两种类型，一种是 TNFα，是一种由 157 个氨基酸组成的蛋白质，通常将它视为细胞因子； 另一种是 TNFβ（称为淋巴毒素），与 TNFα有 35％的同源。这两种类型的 TNF 与相同的受 体结合。TNFβ是由 T 细胞和 B 细胞产生的。", "kps": "", "kp": "ch12_s7_48"}, {"id": "ch12_term_16", "modI": 7, "term": "comet assay", "def": "comet assay 的中文名称是彗星电泳法。彗星电泳法是通过细胞生化特征变化鉴定细胞 凋亡的一种方法。其原理是将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进 行短时间的电泳，并用荧光染料染色，凋亡细胞中形成的 DNA 降解片段，在电场中泳动速 度较快，使细胞核呈现出一种彗星式的图案；而正常的无 DNA 断裂的核在泳动时保持圆球 形。", "kps": "", "kp": "ch12_s7_50"}]}], "mcq": [{"id": "ch12_mcq_1", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "有关动物细胞凋亡最重要的特征，下列说法错误的是（        ）。", "o": ["A．整个过程中细胞质膜始终保持完整", "B．细胞内含物不发生细胞外泄漏", "C．不引发机体的炎症反应", "D．细胞表面的特化结构消失 【答案】D  【解析】动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。"], "a": "D", "e": "动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发 生细胞外泄漏，不引发机体的炎症反应。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_2", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "细胞凋亡的一个重要特点是（     ）。", "o": ["A．DNA 随机断裂", "B．DNA 发生核小体间的断裂", "C．70S 核糖体中的 rRNA 断裂", "D．80S 核糖体中 rRNA 断裂 【答案】B  【解析】凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。"], "a": "B", "e": "凋亡细胞 DNA 链断裂发生在核小体间，而不是随机的；C、D 两个选项并不是凋 亡细胞的特征。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_3", "mod": "1.1 细胞凋亡的研究方法", "modI": 4, "q": "细胞凋亡 DNA 双链的断裂的主要部位是（    ）。", "o": ["A．富含 AT 的区域", "B．富含 GC 的区域", "C．核小体之间的连接区", "D．已经发生 DNA 损伤的部位 【答案】C  【解析】细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。"], "a": "C", "e": "细胞凋亡发生的直接原因是细胞核内的核酸酶被激活，这种核酸酶的切割作用主要 发生在核小体间的 DNA 链。", "kp": "ch12_s4_22"}, {"id": "ch12_mcq_4", "mod": "绪论 · 概览", "modI": 0, "q": "关于细胞凋亡与坏死的区别，下列说法错误的是（       ）。", "o": ["A．细胞凋亡和细胞坏死都是细胞程序性主动性死亡", "B．凋亡细胞和坏死细胞 DNA 电泳都呈“梯状”", "C．细胞凋亡时不伴有局部的炎症反应；而细胞坏死时伴有局部的炎症反应", "D．细胞凋亡时，胞膜及细胞器相对完整；细胞坏死时，胞膜破裂细胞结构溶解 【答案】B  【解析】凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。"], "a": "B", "e": "凋亡细胞 DNA 电泳呈“梯状”；坏死细胞 DNA 电泳呈不规则弥散状。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_5", "mod": "绪论 · 概览", "modI": 0, "q": "下列哪个选项不是衰老细胞结构的变化？（      ）", "o": ["A．有序排列的内质网不复存在，内质网成分弥散性的分布于核周胞质中", "B．线粒体的数量减少而体积增大，内容物呈现网状化并形成多囊体", "C．致密体数量大大减少，几近消失", "D．质膜处于凝胶相或固相；细胞间间隙连接减少 【答案】C  【解析】致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。"], "a": "C", "e": "致密体是衰老细胞中常见的一种结构，绝大多数细胞在衰老时都会有致密体的积累。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_6", "mod": "绪论 · 概览", "modI": 0, "q": "对于体外培养的人二倍体细胞，决定其衰老的主要因素是（         ）。", "o": ["A．细胞培养的外环境", "B．细胞核", "C．细胞质", "D．以上都不是 【答案】B  【解析】Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。"], "a": "B", "e": "Hayflick 等的研究表明，决定细胞衰老的因素在细胞内部，而不在外部环境；是细 胞核而不是细胞质，决定细胞衰老的表达。", "kp": "ch12_s0_2"}, {"id": "ch12_mcq_7", "mod": "绪论 · 概览", "modI": 0, "q": "根据细胞的寿命可以粗略地分为三类：①寿命接近于动物的整体寿命；②缓慢更新的细 胞，其寿命比机体的寿命短；③快速更新的细胞。下列细胞中，属于第一类的细胞是（         ）。", "o": ["A．神经元、脂肪细胞、肌细胞", "B．肝细胞、胃壁细胞", "C．表皮细胞、红细胞和白细胞", "D．肾皮质细胞、骨细胞、角膜上皮细胞 【答案】A  【解析】胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。"], "a": "A", "e": "胃壁细胞属于更新较慢的细胞，角膜上皮细胞、表皮细胞、红细胞、白细胞属于快 速更新细胞。", "kp": "ch12_s0_2"}, {"id": "ch12_mcq_8", "mod": "3.3 “端粒时钟学说/有丝分裂钟”", "modI": 3, "q": "下列哪一项不是 P53 的正常功能？（    ）", "o": ["A．激活细胞周期抑制因子的转录", "B．在 Dy4A 修复中起作用", "C．触发损伤细胞的凋亡", "D．在小鼠胚胎发育中起基本作用 【答案】D  【解析】P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。"], "a": "D", "e": "P53 是著名的肿瘤抑制因子，通过诱导细胞凋亡或生长停滞，避免细胞因为 DNA 的损伤而发生癌变。P53 能识别失去功能的端粒，继而诱导 P21 的表达，控制 CDK 的活化， 使得 Rb 不能被磷酸化，E2F 持续处于失活状态，最终引发衰老。P53 在 DNA 修复中也有 重要作用。", "kp": "ch12_s3_15"}, {"id": "ch12_mcq_9", "mod": "绪论 · 概览", "modI": 0, "q": "下列不属于细胞衰老的特征的是（      ）。", "o": ["A．线粒体数目减少，核膜皱襞", "B．核明显变化为核固缩，常染色质减少", "C．脂褐素减少，细胞代谢能力下降", "D．原生质减少，细胞形状改变 【答案】C  【解析】细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。"], "a": "C", "e": "细胞衰老的特征： （1）细胞内水分减少，致使细胞脱水收缩，体积变小； （2）细胞色素颗粒沉积增多，如脂褐素在胞浆中沉积随老年化过程而增加，如肝细胞、肌 细胞和神经细胞中的积聚更为明显； （3）细胞器的衰老变化：①细胞膜的流动性降低：衰老的细胞膜发生脂质过氧化反应，流 动性明显减弱，因而细胞的兴奋性降低；②线粒体的数量随着年龄的增大而减少，而其体积 则随着年龄的增大而增大；③高尔基复合体的分泌功能与囊泡运输功能下降；溶酶体酶活性 降低；内质网数量减少； （4）细胞核的变化：染色质固化，核膜内折； （5）化学组成与生化反应的改变：①蛋白质合成的速度下降；②细胞内酶的活性与含量改 变等。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_10", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "细胞凋亡和细胞坏死过程中都发生的现象是(                   )。", "o": ["A．保持细胞膜的完整性", "B．释放细胞内含物到胞外", "C．基因组 DNA 的降解", "D．引起周围组织的炎症反应 【答案】C  【解析】细胞凋亡过程中，细胞质膜反折，包裹断裂的染色质片段或细胞器，然后逐渐分离， 形成众多的凋亡小体，凋亡小体则被邻近的细胞所吞噬。整个过程中，细胞质膜的完整性保 持良好，死亡细胞的内容物不会逸散到胞外环境中去，因而不引发炎症反应。在细胞坏死时， 细胞质膜发生渗漏，细胞内容物，包括膨大和破碎的细胞器以及染色质片段，释放到胞外， 导致炎症反应。凋亡通常是生理性变化，而细胞坏死则是病理性变化。"], "a": "C", "e": "细胞凋亡过程中，细胞质膜反折，包裹断裂的染色质片段或细胞器，然后逐渐分离， 形成众多的凋亡小体，凋亡小体则被邻近的细胞所吞噬。整个过程中，细胞质膜的完整性保 持良好，死亡细胞的内容物不会逸散到胞外环境中去，因而不引发炎症反应。在细胞坏死时， 细胞质膜发生渗漏，细胞内容物，包括膨大和破碎的细胞器以及染色质片段，释放到胞外， 导致炎症反应。凋亡通常是生理性变化，而细胞坏死则是病理性变化。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_11", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "下列分子哪些与细胞凋亡有关?（                 ）。", "o": ["A．磷脂酰丝氨酸", "B．磷脂酰乙醇胺", "C．磷脂酰胆碱", "D．磷脂酰肌醇 【答案】A  【解析】当细胞凋亡时，膜内侧磷脂酰丝氨酸外翻到膜表面，胞膜结构仍然完整，最终可将 凋亡细胞遗骸分割包裹为几个凋亡小体，无含容物外溢，因此不引起周围的炎症反应，凋亡 小体可迅速被周围专职或非专职吞噬细胞吞噬。"], "a": "A", "e": "当细胞凋亡时，膜内侧磷脂酰丝氨酸外翻到膜表面，胞膜结构仍然完整，最终可将 凋亡细胞遗骸分割包裹为几个凋亡小体，无含容物外溢，因此不引起周围的炎症反应，凋亡 小体可迅速被周围专职或非专职吞噬细胞吞噬。", "kp": "ch12_s7_50"}, {"id": "ch12_mcq_12", "mod": "1.2 The apoptosis in", "modI": 5, "q": "在 caspases 家族中，起细胞凋亡执行者作用的是（               ）。", "o": ["A．caspase-1，-4，-11", "B．caspase-2，-8，-9", "C．caspase-3，-6，-7", "D．caspase-3，-5，-10 【答案】B  【解析】凋亡起始者包括 caspase-2，-8，-9，-10，-11；凋亡执行者包括 caspase-3，-6，-7。"], "a": "B", "e": "凋亡起始者包括 caspase-2，-8，-9，-10，-11；凋亡执行者包括 caspase-3，-6，-7。", "kp": "ch12_s5_43"}, {"id": "ch12_mcq_13", "mod": "绪论 · 概览", "modI": 0, "q": "下列哪项不属于细胞衰老的特征？（                   ）", "o": ["A．原生质减少，细胞形状改变", "B．细胞膜磷脂含量下降，胆固醇含量上升", "C．线粒体数目减少，核膜内折", "D．脂褐素减少，细胞代谢能力下降 【答案】D  【解析】细胞衰老的特征之一是细胞色素颗粒沉积增多：如脂褐素在胞浆中沉积随老年化过 程而增加，在肝细胞、肌细胞和神经细胞中的积聚更为明显。"], "a": "D", "e": "细胞衰老的特征之一是细胞色素颗粒沉积增多：如脂褐素在胞浆中沉积随老年化过 程而增加，在肝细胞、肌细胞和神经细胞中的积聚更为明显。", "kp": "ch12_s0_0"}, {"id": "ch12_mcq_14", "mod": "1.2.3 哺乳动物细胞凋亡的", "modI": 7, "q": "下列关于细胞凋亡说法中，哪项不正确？（               ）", "o": ["A．细胞凋亡是一种正常的生理现象", "B．细胞凋亡受多种因素影响", "C．细胞凋亡过程是受调控的过程", "D．细胞凋亡的形态学特征是细胞结构的全面溶解 【答案】D  【解析】细胞凋亡最重要的特征是整个过程中细胞膜始终保持完整，细胞内含物不泄漏到细 胞外。"], "a": "D", "e": "细胞凋亡最重要的特征是整个过程中细胞膜始终保持完整，细胞内含物不泄漏到细 胞外。", "kp": "ch12_s7_50"}], "judge": [{"id": "ch12_judge_1", "modI": 0, "q": "通常情况下，体外培养的成纤维细胞的增殖能力与供体年龄有关。（         ）", "a": "对", "e": "如从胎儿肺得到的成纤维细胞可在体外条件下传代 50 次，而从成人肺得到的成纤 维细胞只能传代 20 次。", "kp": "ch12_s0_2"}, {"id": "ch12_judge_2", "modI": 4, "q": "细胞凋亡与细胞坏死一般都不会引起细胞的炎症反应。（          ）", "a": "错", "e": "细胞凋亡与坏死不同，凋亡过程中内含物不泄出，通常不引起细胞炎症反应。", "kp": "ch12_s4_23"}, {"id": "ch12_judge_3", "modI": 4, "q": "凋亡小体只能被吞噬细胞所吞噬。（         ）", "a": "错", "e": "凋亡小体为邻近的细胞所吞噬，但并非完全为吞噬细胞所吞噬。", "kp": "ch12_s4_26"}, {"id": "ch12_judge_4", "modI": 4, "q": "决定秀丽新小杆线虫细胞自杀性死亡的细胞杀手是基因 cdc-9 而不是基因 cdc-3 和 cdc-4。 （     ）", "a": "错", "e": "杀手基因是基因 ced-3，基因 ced-9 的产物是存活因子。", "kp": "ch12_s4_36"}, {"id": "ch12_judge_5", "modI": 4, "q": "细胞坏死往往会引起炎症，而程序性细胞死亡不会引起炎症，根本原因是细胞是否破裂。 （     ）", "a": "对", "e": "程序性细胞死亡不会导致细胞破裂，因而不会有伤口，也就不会引起感染。", "kp": "ch12_s4_23"}, {"id": "ch12_judge_6", "modI": 5, "q": "最据 caspase 蛋白在细胞程序性死亡中的作用，将它们分为三大类：调节物、衔接物和效 应物。caspase-9 属于调节物。（  ）", "a": "错", "e": "所有的 caspase 都是效应物。", "kp": "ch12_s5_43"}, {"id": "ch12_judge_7", "modI": 6, "q": "程序性死亡的细胞之所以能够被吞噬细胞识别和吞噬，是因为这些细胞的表面具有被吞 噬的信号，目前研究得最清楚的被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂 酰乙醇胺分子。（         ）", "a": "错", "e": "被吞噬信号是存在于程序性死亡细胞质膜脂双层外叶的磷脂酰丝氨酸。", "kp": "ch12_s6_45"}, {"id": "ch12_judge_8", "modI": 0, "q": "通常未分化细胞的核质比高而衰老细胞的核质比低。（         ）", "a": "错", "e": "衰老细胞内水分减少，致使细胞脱水收缩，体积变小，染色质固化，核膜内折，所 以核质比高。", "kp": "ch12_s0_3"}, {"id": "ch12_judge_9", "modI": 4, "q": "凋亡小体中的染色质块外一般包有核膜来源的双层膜结构。（          ）", "a": "错", "e": "凋亡起始时骨架杂乱，细胞间接触消失，细胞间粘附力下降；细胞质和核浓缩，显 微镜下观察可发现细胞膜发泡，染色质凝集，沿着核膜形成新月形帽状结构；随着细胞膜内 折，染色质断裂成片断，染色质片断及线粒体等细胞器反折的细胞膜包围并逐渐分开，形成 单个的凋亡小体。", "kp": "ch12_s4_26"}, {"id": "ch12_judge_10", "modI": 3, "q": "蛙发育过程中尾巴的退化涉及细胞的程序性死亡和细胞坏死过程。（                   ）", "a": "错", "e": "蛙发育过程不涉及细胞坏死过程。", "kp": "ch12_s3_17"}, {"id": "ch12_judge_11", "modI": 7, "q": "Caspase 在介导细胞凋亡的过程中，几乎从不完全降解一种蛋白质。                 （  ）", "a": "对", "e": "", "kp": "ch12_s7_62"}, {"id": "ch12_judge_12", "modI": 3, "q": "编程性死亡是导致细胞衰老的一个重要原因。（                     ）", "a": "对", "e": "", "kp": "ch12_s3_16"}], "fill": [{"id": "ch12_fill_1", "modI": 3, "q": "动物细胞程序性死亡的 3 种方式是______、______和______。", "a": "凋亡；坏死；自噬", "kp": "ch12_s3_17"}, {"id": "ch12_fill_2", "modI": 7, "q": "Bcl-2 是一种______（原癌／抑癌）基因，p53 是______基因。", "a": "原癌；抑癌", "kp": "ch12_s7_58"}, {"id": "ch12_fill_3", "modI": 7, "q": "细胞凋亡检测的方法有______、______、______、______和______。", "a": "形态学检测；DNA 电泳；TUNEL 测定法；彗星电泳法；流式细胞分析法", "kp": "ch12_s7_50"}, {"id": "ch12_fill_4", "modI": 0, "q": "细胞衰老的主要学说有______和______。", "a": "氧自由基理论；有丝分裂钟学说", "kp": "ch12_s0_0"}, {"id": "ch12_fill_5", "modI": 0, "q": "衰老是机体在退化时期生理功能下降和紊乱的综合表现，是不可逆的生命过程。就其产 生的性质来说，有三种不同的类型：（1）______衰老；（2）______衰老；（3）______衰 老。", "a": "生理性；病理性；心理性", "kp": "ch12_s0_3"}, {"id": "ch12_fill_6", "modI": 7, "q": "细胞死亡有两种形式；一种为______死亡，另一种为______死亡。前者是受到______而 造成的细胞崩溃裂解；后者是细胞在一定的______或______条件下按照自身的程序结束其生 存。", "a": "坏死性；程序性；侵袭；生理；病理", "kp": "ch12_s7_50"}, {"id": "ch12_fill_7", "modI": 7, "q": "从细胞的寿命看，胃壁细胞属于______的细胞，而角膜上皮细胞属于______的细胞。", "a": "更新缓慢；快速更新", "kp": "ch12_s7_50"}, {"id": "ch12_fill_8", "modI": 0, "q": "1961 年，Hayflick 发现体外培养的人成纤维细胞具有增殖分裂的极限。来自胚胎的成纤 维细胞分裂传代______次后开始衰老和死亡，而来自成年组织中的成纤维细胞只能培养 ______次就开始死亡。", "a": "50；15～30", "kp": "ch12_s0_2"}, {"id": "ch12_fill_9", "modI": 4, "q": "______年的诺贝尔生理学和医学奖授予了在器官发育和程序性细胞死亡研究领域中做出 奠基性贡献的三位科学家：英国的 Brenner、Sulston 和美国的 Horvitz。他们创造性地用______ 作为实验模型，实现了对器官发育过程中的______、______的原位观察，完成了______的绘 制，在此基础上发现并研究了调控器官发育______的关键基因。", "a": "2002；线虫；细胞分裂；分化；细胞图谱；程序性细胞死亡", "kp": "ch12_s4_30"}, {"id": "ch12_fill_10", "modI": 4, "q": "秀丽新小杆线虫的细胞程序性死亡涉及的基因大致分为四组：①______基因，如 Ces-1 和 ces-2 基因；②______基因，即 ced-3、ced-4、ced-9 和 egl-1；③______基因，即 ced-1、 ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；④______基因如核酸酶基因 1，即 muc-1 基 因。", "a": "决定死亡的；执行死亡的；死亡细胞被吞噬细胞所吞噬的；死亡细胞在吞噬体中被 降解的", "kp": "ch12_s4_38"}, {"id": "ch12_fill_11", "modI": 0, "q": "细胞衰老机理的假说可以归纳为两类：______和______。", "a": "复制衰老；胁迫诱导的早熟性衰老", "kp": "ch12_s0_0"}, {"id": "ch12_fill_12", "modI": 7, "q": "诱导细胞凋亡的因子可以分为______和______两大类。", "a": "物理性因子；化学及生物因子", "kp": "ch12_s7_50"}, {"id": "ch12_fill_13", "modI": 5, "q": "一般情况下，抑制动物细胞内的 PI3／Tor 信号通路，可诱导细胞发生______。", "a": "自噬", "kp": "ch12_s5_40"}, {"id": "ch12_fill_14", "modI": 0, "q": "酵母细胞衰老的机制是______。", "a": "ERC 的积累", "kp": "ch12_s0_0"}, {"id": "ch12_fill_15", "modI": 7, "q": "年轻的功能健全的细胞的膜相是典型的______相。衰老的或者是缺陷的膜通常处于 ______相或______相。", "a": "液晶；凝胶；固相", "kp": "ch12_s7_50"}, {"id": "ch12_fill_16", "modI": 5, "q": "线虫中的 ced9 基因的功能是 。", "a": "抑制细胞凋亡", "kp": "ch12_s5_40"}, {"id": "ch12_fill_17", "modI": 4, "q": "根据细胞死亡诱因的不同，将编程性细胞死亡分为：_________和_________。", "a": "细胞凋亡；细胞自噬", "kp": "ch12_s4_37"}, {"id": "ch12_fill_18", "modI": 7, "q": "肿瘤坏死因子 TNF 消除肿瘤细胞的机制是通过______。", "a": "caspases 依赖性细胞凋亡途径", "kp": "ch12_s7_48"}], "term": [{"id": "ch12_term_1", "modI": 0, "term": "细胞凋亡（apoptosis）。", "def": "细胞凋亡（apoptosis）是一种有序的或程序性的细胞死亡方式，是细胞接受某些特定信 号刺激后进行的正常生理应答反应。该过程具有典型的形态学和生化特征，凋亡细胞最后以 凋亡小体被吞噬消化。", "kps": "", "kp": "ch12_s0_0"}, {"id": "ch12_term_2", "modI": 7, "term": "亡复合体（apotosome）。", "def": "凋亡复合体（apotosome）是指凋亡分子 Apaf-1 与细胞色素 c 形成的复合体，相对分子 量为（700～1400）×103，细胞质中 Caspase-9 的前体被募集到复合体上并发生自动切割活化， 引起细胞凋亡。", "kps": "", "kp": "ch12_s7_51"}, {"id": "ch12_term_3", "modI": 7, "term": "aspase 募集结构域（Caspase recruitment domain，CARD）。", "def": "存在于凋亡起始 Caspase-2 和-9，以及凋亡相关接头蛋白分子中，通过结构域之间的聚 合，Caspase 能够彼此结合或与接头蛋白结合，被募集到上游信号复合物中活化。", "kps": "", "kp": "ch12_s7_48"}, {"id": "ch12_term_4", "modI": 4, "term": "细胞坏死（necrosis）。", "def": "细胞坏死（necrosis）是细胞“程序性死亡”的另一种形式，具有包括引发炎症反应在内 的重要生理功能。当细胞凋亡不能正常发生而细胞必须死亡时，坏死作为凋亡的“替补”方式 被细胞采用；此外，分裂旺盛细胞的 DNA 被持续损伤，也能引发细胞坏死，推测原因可能 是 RARP 被活化。", "kps": "", "kp": "ch12_s4_23"}, {"id": "ch12_term_5", "modI": 3, "term": "端粒（telomere）。", "def": "端粒（telomere）是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。 对染色体结构稳定、末端复制等有重要作用。端粒常在每条染色体末端形成一顶“帽子”结构。", "kps": "", "kp": "ch12_s3_9"}, {"id": "ch12_term_6", "modI": 0, "term": "成纤维细胞（fibroblast）。", "def": "成纤维细胞是构成纤维性结缔组织的重要成分。细胞特点是：外形长而扁平，常有不规 则的突起；细胞质内含有线粒体、高尔基体、中心体、微脂肪粒等、其他无特殊的分化；细 胞核呈椭圆形，有明显的核仁，细胞核染色性差。成纤维细胞常与胶原纤维紧密相连，因与 胶原纤维的形成有关故称为成纤维细胞。", "kps": "", "kp": "ch12_s0_3"}, {"id": "ch12_term_7", "modI": 5, "term": "阻遏（repression）。", "def": "阻遏是指基因的表达在信使 RNA 合成（转录）阶段为特异的调节因子（阻遏物）所抑 制，使细胞内特定的酶或酶系合成率降低的现象。当特定的代谢物质在细胞内的浓度增加时， 阻遏物就被活化，而相应结构基因群（操纵子）的特异物质的产生就受到抑制。", "kps": "", "kp": "ch12_s5_42"}, {"id": "ch12_term_8", "modI": 1, "term": "胞质体（cytoplast）。", "def": "胞质体是指除去细胞核后由膜包裹的无核细胞。", "kps": "", "kp": "ch12_s1_7"}, {"id": "ch12_term_9", "modI": 3, "term": "程序性细胞死亡（programmed cell death）。", "def": "程序性细胞死亡是细胞的一种生理性、主动性的“自杀”现象，是主动由基因决定的细胞 自动结束生命的过程。这些细胞死得有规律，似乎是按编好了的“程序”进行的，是生物体在 漫长进化过程中逐步建立的细胞“自杀”机制，其重要作用是清除多余的、受损的、癌变的或 微生物感染的细胞，维持机体内环境的稳定。程序性细胞死亡的类型有多种，细胞凋亡只是 其中之一。", "kps": "", "kp": "ch12_s3_17"}, {"id": "ch12_term_10", "modI": 1, "term": "自由基（free radical）。", "def": "自由基是具有高度活性、通常寿命短暂的分子片段具有的一个或多个未配对电子。自由 基的种类很多，活性最强的是氧中心自由基，简称氧自由基，包括 O2（超氧自由基）、·OH （羟自由基）和 H2O2。", "kps": "", "kp": "ch12_s1_4"}, {"id": "ch12_term_11", "modI": 7, "term": "肿瘤坏死因子（tumor necrosis factor，TNF）。", "def": "肿瘤坏死因子是在体内和体外实验中杀死肿瘤，或抑制组织癌变的因子。人的 TNF 有 两种类型，一种是 TNFα，是一种由 157 个氨基酸组成的蛋白质，通常将它视为细胞因子； 另一种是 TNFβ（称为淋巴毒素），与 TNFα有 35％的同源。这两种类型的 TNF 与相同的受 体结合。TNFβ是由 T 细胞和 B 细胞产生的。", "kps": "", "kp": "ch12_s7_48"}, {"id": "ch12_term_12", "modI": 0, "term": "Hayflick Limitation", "def": "Hayflick Limitation 的中文名称是 Hayflick 界限。Hayflick 界限是指正常细胞在体外培养 的条件下具有有限分裂次数的现象。动物体细胞在体外可传代的次数与物种的寿命有关，细 胞的分裂能力与个体的年龄有关。正常人的成纤维细胞在体外培养条件下，即使条件适宜， 细胞也不能无限制地进行分裂；即使是机体中可以终生分裂的细胞，在体外培养时也有分裂 次数的极限；即使给予丰富的营养、生长因子和足够的生长空间也是如此。", "kps": "", "kp": "ch12_s0_2"}, {"id": "ch12_term_13", "modI": 4, "term": "apoptosis body", "def": "apoptosis body 的中文名称是凋亡小体。凋亡小体是指细胞凋亡时，核染色质断裂为大 小不等的片段，与某些细胞器如线粒体等聚集在一起，被反折的细胞膜所包形成的结构。从 外观看，细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡小体。", "kps": "", "kp": "ch12_s4_23"}, {"id": "ch12_term_14", "modI": 3, "term": "细胞凋亡", "def": "细胞凋亡即程序性细胞死亡（PCD），是指细胞在一定的生理或病理条件下，受内在遗 传机制的控制自动结束生命的过程。细胞凋亡是多细胞有机体为调控机体发育，维护内环境 稳定，由基因控制的细胞主动死亡过程。主要形态特征包括细胞核浓缩、染色体 DNA 被以 核小体为单位切成梯状片段、细胞凋亡小体形成等。", "kps": "", "kp": "ch12_s3_17"}, {"id": "ch12_term_15", "modI": 4, "term": "细胞自噬", "def": "细胞自噬是指细胞通过溶酶体与双层膜包裹的细胞自身物质融合，从而降解细胞自身物 质的过程。。正常的动物细胞为了维持细胞内环境的动态平衡，需要不断降解功能失常或不 需要的细胞结构，如各种蛋白质、细胞器以及各种胞质组分。通常，寿命较短的蛋白质如调 控蛋白等通过泛素-蛋白酶体系统进行降解；而寿命较长的细胞结构及蛋白质通过细胞自噬 途径，由溶酶体进行降解。细胞自噬的特征是细胞中出现大的双层膜包裹的自噬泡即自噬小 体。", "kps": "", "kp": "ch12_s4_26"}, {"id": "ch12_term_16", "modI": 7, "term": "comet assay", "def": "comet assay 的中文名称是彗星电泳法。彗星电泳法是通过细胞生化特征变化鉴定细胞 凋亡的一种方法。其原理是将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进 行短时间的电泳，并用荧光染料染色，凋亡细胞中形成的 DNA 降解片段，在电场中泳动速 度较快，使细胞核呈现出一种彗星式的图案；而正常的无 DNA 断裂的核在泳动时保持圆球 形。", "kps": "", "kp": "ch12_s7_50"}, {"id": "ch12_term_17", "modI": 4, "term": "necrosis", "def": "necrosis 的中文名称是细胞坏死。细胞坏死是区别于细胞凋亡的另一种细胞死亡方式。 当细胞坏死时，细胞质出现空泡，细胞质膜破损，细胞内含物，包括膨大和破碎的细胞器以 及染色质片段释放到胞外，引起周围组织的炎症反应。", "kps": "", "kp": "ch12_s4_23"}], "short": [{"id": "ch12_short_1", "modI": 4, "q": "细胞凋亡的形态学过程。", "a": "凋亡过程在形态上分为 3 个阶段： （1）凋亡的起始。染色质固缩并沿核膜分布，细胞质发生皱缩，细胞表面特化结构消失。 （2）凋亡小体的形成。细胞质膜反折，包围染色质片段和细胞器等，形成芽状突起并逐渐 分隔，形成凋亡小体。 （3）凋亡小体被吞噬。凋亡小体被邻近的细胞或吞噬细胞所吞噬，并被消化后重新利用。 动物细胞凋亡最重要的特征是整个过程中细胞质膜始终保持完整，细胞内含物不发生细胞外 泄漏，不引发机体的炎症反应。", "kp": "ch12_s4_22"}, {"id": "ch12_short_2", "modI": 3, "q": "举例说明细胞凋亡的生物学意义。", "a": "（1）保证个体正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控。 （2）是一种生理性保护机制，清除体内多余、受损或危险的细胞而不对周围的细胞或组织 产生损害。如：神经元细胞数量的调节、器官细胞数量的稳定、成体细胞的自然更新以及病 原体感染细胞的清除等。 （3）细胞凋亡的失调导致疾病：细胞凋亡不足，如肿瘤。细胞凋亡过度，导致自身免疫病 和炎症，如败血症、心肌梗塞、艾滋病、老年痴呆、帕金森病。", "kp": "ch12_s3_17"}, {"id": "ch12_short_3", "modI": 0, "q": "简述细胞凋亡与坏死在形态学上的主要区别。", "a": "两者在形态学上的主要区别是：细胞凋亡过程中，整个细胞固缩，细胞膜反折，包裹断 裂的染色质片断或细胞器，然后逐渐分离，形成众多的凋亡小体，凋亡小体则为邻近的细胞 所吞噬，整个过程中，细胞膜的整合性保持良好，死亡细胞的内容物不会逸散到胞外环境中， 不引发炎症反应。在细胞坏死时，细胞体积膨胀，细胞膜发生渗漏，细胞的内容物释放到细 胞外，导致炎症的发生。", "kp": "ch12_s0_0"}, {"id": "ch12_short_4", "modI": 0, "q": "肿瘤细胞中端粒酶的活性较高，而在正常细胞中检测不到明显的端粒酶活性，这与著名 的 Hayflick 界限有什么关系？", "a": "（1）端粒是染色体末端的一种特殊结构，其 DNA 由简单的串联重复序列组成。随着 细胞的每次分裂，端粒缩短，达到一定的阈值时，细胞进入衰老。端粒酶是一种核糖核蛋白 酶，由 RNA 和蛋白质组成，端粒酶以自身 RNA 为模板催化端粒 DNA 的形成。肿瘤细胞是 变异的非正常细胞，具有端粒酶活性，从而保证了肿瘤细胞的“不死性”特征。 （2）“永生”或“不死”的肿瘤细胞具有无限增殖能力的这一特点，看似与 Hayflick 界限所持 的观点相矛盾，然而“永生”的肿瘤细胞已被证明是不正常的细胞，它们的染色体数目或形态 已经不同于原先的细胞了，因此肿瘤细胞并不在 Hayflck 界限的范畴之内。", "kp": "ch12_s0_0"}, {"id": "ch12_short_5", "modI": 0, "q": "细胞衰老与机体衰亡有何相关性？", "a": "细胞衰老与机体衰亡对单细胞生物来说是一回事。但对多细胞机体来说，二者有其密切 的相关性。细胞衰老不等于机体衰亡，机体衰亡也并不意味着所有细胞同时衰亡。例如，一 些细胞的衰亡可换来另一些细胞的新生，从而换来机体的勃勃生机。如果机体刚刚死亡，一 些细胞依然存活，可用来做器官移植和组织培养等。总之，机体整体的衰亡是细胞衰亡的反 映，一些细胞的衰老又是机体衰亡的基础和直接原因。", "kp": "ch12_s0_0"}, {"id": "ch12_short_6", "modI": 1, "q": "自由基学说的实验基础是什么？", "a": "以实验动物的寿命作为整体实验的标记物，用饮食技巧来研究自由基与衰老的两个方面， 一方面在饮食中减少某种可以提高自由基水平的化合物，如减少铜离子或不饱和价键的化合 物，从而减少自由基反应对机体的损伤；另一方面，加入某些抗氧化剂，可以抑制自由基反 应，清除自由基。如：2-硫基乙胺（2-MEA）、α-生育酚。饲料中添加抗氧化剂可增加小鼠、 大鼠、果蝇、线虫的寿命。如：将 1.0％（wt／wt）的 2-MEA 加到雄性 LAFl 小鼠的饲料中， 在断奶后很短时间开始喂小鼠可增加平均寿命 30％，相当于人的平均寿命从 73 岁增加到 95 岁。", "kp": "ch12_s1_5"}, {"id": "ch12_short_7", "modI": 4, "q": "细胞坏死性死亡有何特点？", "a": "由于某些外界因素造成细胞的急速死亡为坏死性细胞死亡，其特征是细胞膜通透性增加、 细胞外形变得不规则、细胞核及线粒体肿胀、内质网扩散、溶酶体破裂、最终细胞破坏、胞 浆外溢、细胞解体。这种反应常常引起炎症反应。", "kp": "ch12_s4_23"}, {"id": "ch12_short_8", "modI": 5, "q": "酗酒者及肝癌患者的肝细胞都会发生增殖，试阐述其不同的诱发机制。", "a": "（1）酗酒者体内肝细胞增生是由于肝脏负担过重，并被大量应被代谢的酒精所损害， 这就需要更多的肝细胞激活那个通常调节增生的控制机制。如果肝脏没有严重损坏，在酗酒 者停止饮酒后，肝通常会恢复为原来大小。 （2）在肝癌中，突变破坏正常的细胞增殖控制而使细胞不受控制地持续分裂。", "kp": "ch12_s5_42"}, {"id": "ch12_short_9", "modI": 3, "q": "简述参与秀丽新小杆线虫的细胞程序性死亡基因的分组及相关作用。", "a": "参与秀丽新小杆线虫的细胞程序性死亡的 15 个基因，根据其作用不同大致可分为四组。 （1）第 1 组含同 PCD 有关的决定死亡的两个基因，即 ces-1（ces 表示 CE 细胞存活的调控 基因）和 ces-2 基因，即该组基因在线虫 CE 的 PCD 调控具有重要意义；（2）第 2 组含有 执行死亡的四个基因：ced-3（cell death）、ced-4、ced-9 和 eg-1 基因；（3）第 3 组含有 7 个与死亡细胞被吞噬细胞所吞噬的基因，即 ced-1、ced-2、ced-5、ced-6、ced-7、ced-10 和 ced-11；（4）第 4 组是死亡细胞在吞噬体中被降解的基因，如核酸酶基因 l，即 nuc-1 基因， 如果 nuc-1 发生突变，则 DNA 裂解受阻，但不能抑制细胞死亡，表明此核酸酶并非 PCD 所 必需。由这四组基因共同作用导致线虫细胞的程序化死亡。", "kp": "ch12_s3_17"}, {"id": "ch12_short_10", "modI": 3, "q": "如何证明细胞程序死亡受到相关基因的正、负调控？试以线虫为例作简要说明。", "a": "（1）线虫发育过程中有 131 个细胞注定要程序死亡，已经证明有 11 种基因与该程序死 亡有关，其中 3 种与程序死亡的开始有关。（2）其中 ced3 和 ced4 基因是细胞程序死亡所 必需的，在 ced3 和 ced4 突变株中，原来要死亡的细胞可以生存，ced3 和 ced4 属于正调控 基因。（3）ced9 基因对 ced3 和 eed4 行使负调控。因为观察到表达 ced9 的突变株中，上述 细胞不进入程序死亡，而在野生型中这些细胞要凋亡。", "kp": "ch12_s3_17"}, {"id": "ch12_short_11", "modI": 6, "q": "根据图 16-1 分析比较线虫与脊椎动物细胞程序化死亡相关的基因及其调节。 图 16-1", "a": "（1）线虫和脊椎动物细胞程序性死亡过程的相似点 在线虫和脊椎动物的细胞程序性死亡调节过程中，都有调节子、接合子、效应子三类分子， 且存在一一对应的同源性基因。调节子抑制接合子的活性，使细胞程序性死亡处于关闭状态。 当细胞程序性死亡受激活信号打开之后，调节子对接合子的抑制作用解除，接合子激活下游 的效应分子，这些效应分子最终导致细胞程序性死亡。 （2）线虫和脊椎动物细胞程序性死亡过程的不同点 脊椎动物的细胞程序性死亡过程中，在接合子的激活下效应子 caspase-9 并不直接导致细胞 的程序性死亡，而是通过激活下游 caspase-3，接着 caspase-3 诱导细胞的程序性死亡。整个 过程较线虫复杂。", "kp": "ch12_s6_45"}, {"id": "ch12_short_12", "modI": 6, "q": "简述 caspases 导致细胞凋亡的机制和 caspases 活化的基本途径。 相关试题：试述细胞程序性死亡的基因调控机制。", "a": "（1）caspases 导致细胞凋亡的机制 ①外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启凋亡反应。 ②内源途径 线粒体接收到凋亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞凋亡。 ③外、内源途径的关联 a．外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可 以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径； b．凋亡的内源途径被激活后，线粒体上释放的促凋亡因子 Smac 也能够活化 caspase-8。 （2）caspases 活化途径 ①经细胞表面受体活化 caspase-2、-8、-10，通过这几个再活化 caspase-3、-7 等凋亡执行因 子，启动凋亡过程。 ②经线粒体中的细胞色素 c 激活 caspase-9，再由 caspase-9 激活下游凋亡执行因子，启动细 胞凋亡。", "kp": "ch12_s6_45"}, {"id": "ch12_short_13", "modI": 7, "q": "在活化的细胞毒性 T 淋巴细胞中存在一种称为“粒酶”（granzyme）的丝氨酸蛋白酶，它 同样具有天冬氨酸特异性，能使具有毒性的细胞诱发其靶细胞凋亡，请详细谈一谈“粒酶” 是如何使癌化的细胞或病毒感染的细胞发生凋亡的。", "a": "“粒酶”使癌化的细胞或病毒感染的细胞发生凋亡的过程如下： （1）在靶细胞外，粒酶 B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离。 （2）粒酶 B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白。进入靶细胞后，粒酶 B 通过 caspases 依赖性和 caspases 非依赖性途径促进细胞凋亡。粒酶 B 切割并活化促凋亡因子 Bid， 活化的 Bid 转移到线粒体外膜，改变其通透性，释放 Cyt c 等促凋亡因子，引发 caspases 级 联反应，诱导细胞凋亡。 （3）粒酶 B 还可通过切割凋亡抑制因子 Mcl-1 诱发细胞凋亡内源性途径。", "kp": "ch12_s7_50"}, {"id": "ch12_short_14", "modI": 7, "q": "简述当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径。", "a": "当细胞受到损伤或发生应激反应时，依赖线粒体的细胞凋亡途径如下： （1）引起细胞凋亡的胞内信号 DNA 损伤、细胞质中 Ca2 浓度过高、极度氧胁迫产生大量自由基等。内源信号中也有抑制 ＋   细胞死亡的负控制信号，如哺乳动物中的 Bcl-2 和 Bcl-X 蛋白。 （2）Bcl-2 蛋白家族对于细胞凋亡的影响 其中有些成员促进凋亡，如 Bad、Bid、Bax；有些成员抑制凋亡，如 Bcl-2、Bcl-XL、BCl-w。 Bcl-2 蛋白定位于线粒体外膜，有双重功能：一是阻止 Cyt c 从线粒体中释放，二是与 Apaf-1 结合。 （3）依赖于线粒体的细胞凋亡途径 当细胞受到损伤或发生应激反应时，激活了 Bcl 家族中的促凋亡蛋白（如 Bad、Bax），这 些蛋白从细胞质转移到线粒体外膜并插入外膜，导致线粒体外膜的通透性发生改变，然后 Cyt c 从线粒体释放到细胞质，进入胞质的 Cyt c 与 Apaf-1、carpase-9 前体等装配成多亚基 蛋白复合体，caspase-9 在凋亡复合体中发生自身切割而活化，激活的 caspase-9 作为起始 caspases 激活下游的执行 caspases，然后执行 caspases 作用于靶蛋白引发细胞程序性死亡， 即细胞凋亡。", "kp": "ch12_s7_50"}, {"id": "ch12_short_15", "modI": 0, "q": "细胞衰老有哪些特征？", "a": "细胞衰老表现为对环境变化适应能力的降低和维持细胞内环境恒定能力的降低，不仅形 态学结构发生改变，分子水平的变化也显而易见。细胞衰老的主要特征表现如下： （1）在结构上表现为退行性变化，细胞数目减少、细胞体积缩小。细胞内水分减少，从而 使得原生质硬度增加，造成细胞收缩、失去正常形态。细胞质膜流动性降低。而在原生质改 变的同时，细胞核也发生固缩，结构不清，染色质加深，细胞核与细胞质比率减小或核消失。 同时线粒体数量减少而体积增大。 （2）伴随着细胞的衰老，细胞内各种大分子的组成也发生改变，如蛋白质合成下降。细胞 内蛋白质发生糖基化、氨甲酰化、脱氨基等修饰反应，导致蛋白质稳定性、抗原性、可消化 性下降，自由基使蛋白质多肽断裂、交联而变性，氨基酸由左旋变为右旋。酶分子活性中心 被氧化，金属离子 Ca2 、Zn2 、Mg2 、Fe2 等丢失，最终酶失活。 ＋     ＋  ＋  ＋   （3）DNA 复制与转录受到抑制，但也有个别基因会异常激活，端粒 DNA 丢失，线粒体 DNA 特异性缺失，DNA 氧化、断裂、缺失和交联，甲基化程度降低。 （4）mRNA 和 tRNA 含量降低。", "kp": "ch12_s0_0"}, {"id": "ch12_short_16", "modI": 4, "q": "对于多细胞生物，细胞凋亡的生理意义何在？", "a": "多细胞生物细胞凋亡的生理意义如下： （1）细胞凋亡对动物个体的正常发育，自稳态的维持，免疫耐受的形成，肿瘤监控，抵御 外界各种因素的干扰等多种生理及病理过程具有重要意义。 （2）细胞凋亡是一种生理性保护机制，能够清除体内多余、受损或危险的细胞而不对周围 的细胞或组织产生损害。 ①成体细胞的自然更新，通过细胞凋亡来完成被病原体感染的细胞的清除； ②各种杀伤细胞对被感染细胞进行攻击并导致其死亡，也是基于细胞的凋亡。 （3）在成熟的动物个体中，机体通过调节细胞凋亡和细胞增殖的速率来维持组织器官细胞 数量的稳定。 （4）动物发育过程中，细胞凋亡是塑造个体及器官形态的机制之一。", "kp": "ch12_s4_25"}, {"id": "ch12_short_17", "modI": 0, "q": "什么是“Hayflick 界限”？", "a": "“Hayflick 界限”是指正常细胞在体外培养的条件下具有有限分裂次数的现象。动物体细 胞在体外可传代的次数与物种的寿命有关，细胞的分裂能力与个体的年龄有关。正常人的成 纤维细胞在体外培养条件下，即使条件适宜，细胞也不能无限制地进行分裂；即使是机体中 可以终生分裂的细胞，在体外培养时也有分裂次数的极限；即使给予丰富的营养、生长因子 和足够的生长空间也是如此。这种在体外培养的细胞增殖传代的能力，反映了细胞在体内的 衰老状况。", "kp": "ch12_s0_0"}], "calc": [{"id": "ch12_calc_1", "modI": 0, "q": "什么是细胞衰老？细胞衰老有哪些特征？", "a": "细胞的衰老是指体外培养的正常细胞经过有限次数的分裂后，停止分裂，细胞形态和生 理代谢活动发生显著改变的现象。 一般指细胞的形态、结构、化学成分和生理功能逐渐衰退的总现细胞衰老的主要特征有如下 几个方面： （1）衰老过程中细胞质膜体系的变化。细胞质膜体系的变化包括：细胞表面电荷的变化， 年老细胞表面蛋白多糖组成的变化，衰老细胞膜的渗漏引起外界钙的大量进入细胞质；内质 网排列变得无序。 （2）衰老过程中细胞骨架体系的变化。细胞骨架被认为是细胞代谢功能的调节者，尤其是 微丝系统与细胞增殖和细胞分化的调节直接相关。细胞骨架的改变包括微丝系统的结构和成 分发生变化和核骨架的变化。 （3）衰老过程中线粒体的变化。研究结果表明，细胞中线粒体的数量随着年龄的增大而减 少。有人认为线粒体是细胞衰老的生物钟。 （4）细胞核的变化。细胞核体积增大，核膜内折；染色质固缩化是衰老细胞核中另一个重 要变化，染色体端粒的变化。 （5）衰老过程中蛋白质合成的变化。在细胞衰老过程中蛋白质合成速度降低，原因是由于 核糖体的效率和准确性降低及蛋白质合成延伸因子的数量和活性降低所造成。另外在细胞衰 老过程中蛋白质合成发生变化的另一个特点是，一些特异蛋白的出现或原有蛋白质发生衰老 有关的结构上的改变。 （6）原生质与水分的减少。细胞到了衰老期，细胞内的生活物质逐渐减少，而原生质中出 现一些非生命物质。另外，衰老细胞常发生水分减少的现象，结果使细胞收缩，体积缩小， 失去正常的球形。 （7）酶的活性与含量的变化。衰老细胞内酶的活性变化和含量的增减，也可能与细胞衰老 有密切关系。 （8）色素的生成和蜡样物质的沉积。许多细胞内色素的生成，随着衰老而增加。有人发现 猕猴的神经细胞内，脂褐素的增加与动物年龄增长存在着平行关系。 强的核外染色物质多，反之，在衰老细胞就少。 （10）核质比例减少。细胞核与细胞质的比例逐渐减小，生长速度也逐渐降低，甚至有的细 胞最后连核都消失掉。", "kp": "ch12_s0_0"}, {"id": "ch12_calc_2", "modI": 1, "q": "自由基如何对细胞产生伤害？", "a": "细胞内自由基的浓度过高时，常与生物大分子发生反应，破坏了生物大分子的结构，从 而伤害了细胞，这些反应包括： （1）自由基与核酸分子中的碱基发生加成反应，OH·等加到碱基（胸腺嘧啶 C6 或 C5，腺嘌 呤 C8）的双链上，破坏碱基可产生基因突变。 （2）自由基可加成到膜脂及其他脂类不饱和脂肪酸的双链中，引起脂质过氧化，并可产生 新的自由基。如脂质过氧化可使线粒体损伤，导致能量代谢障碍；微粒体损伤，使多聚核糖 体解聚，抑制蛋白质合成；溶酶体损伤可使溶酶体膜通透性改变，使机体受到更大损伤。 （3）自由基常攻击肽链上的脯氨酸残基，引入羰基而生成α-吡咯烷酮，经水解与其相邻氨 基酸断开，造成蛋白质断裂。此外自由基还引起蛋白质交联、蛋白质残基侧链基发生改变、 破坏蛋白质高级结构等。 （4）自由基的氧化损伤涉及到细胞骨架蛋白。如肌动蛋白是构成微丝的主要蛋白质，其 4 个—SH 可成为氧化的对象，肌动蛋白与氧化型谷胱甘肽之间形成二硫键可导致分子表面电 荷的改变；在老化的红细胞中也可检测出类似的修饰物，用醌处理的细胞中也发现不同肌动 蛋白分子或肌动蛋白与其他蛋白质之间形成二硫键，这种氧化性蛋白质交联引起大分子的聚 集。", "kp": "ch12_s1_6"}, {"id": "ch12_calc_3", "modI": 3, "q": "什么是细胞程序性死亡？试述细胞程序化死亡的基因调控机制。", "a": "细胞程序性死亡是细胞按某种预定程序进行的生理性的自然死亡过程，它是有机体生长 发育过程中不可缺少的环节。 （1）死亡受体介导的细胞凋亡：死亡受体属肿瘤坏死因子基因家族，其共同特征都有相似 的、富含半胱氨酸的细胞外结构域。死亡受体还有一个同源的、被称为死亡结构的域的胞内 序列。死亡结构域一般使死亡受体与胞内凋亡机制相连，但有时也会介导与凋亡无关或抑制 凋亡的过程。 （2）线粒体介导的细胞凋亡：在脊椎动物细胞凋亡过程中，线粒体被认为处于凋亡调控的 中心位置。死亡信号诱使线粒体渗透性转换孔开启，导致线粒体跨膜电位的崩解，从而使凋 亡相关活性物质释放，继而对 caspase 酶系激活是细胞凋亡实现的最根本的生物化学途径。 （3）凋亡相关基因：在细胞凋亡的分子生物学研究过程中，发现了有多种基因参与细胞凋 亡的基因调控，其中包括 ced 基因、bel-2 基因、ICE 基因、p53 基因、Fas／Ap0 基因及 c-myc 基因等。随着研究的深入，还发现其他多种可能与凋亡调控有关的基因，只是研究起步较晚， 许多控制机制尚无法阐明。", "kp": "ch12_s3_17"}, {"id": "ch12_calc_4", "modI": 0, "q": "你认为细胞衰老的可能原因有哪些？", "a": "细胞衰老是随着时间的推移，细胞增殖能力和生理功能逐渐下降的变化过程。表现为细 胞在形态上发生明显变化，例如：细胞皱缩，质膜透性和脆性提高，线粒体数量减少，染色 质固缩、断裂等。其原因可归纳为以下几点： （1）端粒的缩短。不同组织细胞端粒长度不同，体外培养细胞的端粒长度随着世代的增加 逐渐缩短；并且在正常的体细胞中端粒酶处于失活状态，如果将活化的端粒酶导入正常的人 成纤维细胞并使其持续表达，结果细胞的端粒不再缩短，而此时细胞的复制寿命增加了近 5 倍。这些证据表明，端粒的缩短能够导致细胞的衰老。其作用机制为：端粒的缩短促使细胞 中 p53 含量增加，继而诱导 p21 的表达，从而抑制 CDK 的活性，使得 Rb 不能被磷酸化， 使 E2F 处于失活状态，细胞因此不能从 G1 期进入 S 期，从而引发细胞衰亡。 （2）胁迫诱导。许多刺激因素如氧化损伤、乙醇、离子辐射、丝裂霉素 C 等均能引起细胞 衰老，这一类的细胞衰老称为胁迫诱导的早熟性衰老（SIPS）。这一类衰老的机制均涉及 p53、p21 以及 p16 的信号转导途径。其中氧化损伤引起的细胞衰老最为重要。活性氧自由 基的危害主要表现为脂褐素的形成、线粒体 DNA 的突变、诱导细胞凋亡、蛋白质合成减少 等，这些都可以诱导细胞衰老的产生。 （3）代谢废物累积。这一类的衰老过程主要存在于单细胞生物中，例如酵母细胞随着有丝 分裂的进行，ERC（染色体外的环形拷贝 rDNA）在母细胞中逐渐积累，它可以掠夺 DNA 正常复制和转录所需要的物质，从而抑制细胞生长，使酵母细胞衰老。", "kp": "ch12_s0_0"}, {"id": "ch12_calc_5", "modI": 7, "q": "何为细胞程序性死亡？有何特征？发生机制如何？ 相关试题：简述细胞凋亡的概念及凋亡细胞的主要变化。", "a": "（1）细胞程序性死亡的概念 细胞程序性死亡是指在发育过程中发生的某类细胞的大量死亡，而这种细胞死亡要求特定的 基因表达。细胞程序性死亡是一个主动的自我调控的过程，其细胞死亡往往受到细胞内某种 由遗传机制决定的“死亡程序”控制。 （2）细胞程序性死亡的特征 ①细胞核：核凝集，核膜皱缩破裂；染色质致密并沿核膜分布；DNA 降解成片段，出现阶 梯状电泳条带。 ②细胞质：浓缩，细胞骨架解体。 ③细胞膜：细胞连接破坏，细胞膜反折包围染色质片段和细胞器内陷成凋亡小体。 （3）细胞程序性死亡的发生机制 死亡信号→激活死亡信号受体→细胞外信号转变成细胞内信号→蛋白酶家族级联反应→底 物蛋白被水解→细胞凋亡发生。分为 caspases 依赖性的细胞程序性死亡和 caspases 非依赖性 的细胞程序性死亡。 ①caspases 依赖性的细胞程序性死亡 a．外源途径 死亡受体如 Fas 在配体 FasL（凋亡信号）的刺激下，通过接头蛋白 FADD 将 caspase-8 酶原 招募到细胞膜上，形成死亡诱导信号复合物 DISC，caspase-8 酶原在这个复合物中进行自体 切割活化，进而切割下游的 caspase-3，使之活化，开启程序性死亡反应。外源途径中的 caspase-8 以及细胞毒性 T 淋巴细胞和自然杀伤细胞分泌的颗粒酶 B，也可以切割并活化 Bcl-2 家族的促凋亡因子 Bid，激活内源凋亡途径。 b．内源途径 线粒体接收到死亡信号后，Cyt c 从线粒体中释放到细胞质中，与凋亡因子 Apaf-1（线粒体 释放）结合形成复合物，Apaf-1 通过 CARD 结构域招募细胞质中的 caspase-9 酶原，caspase-9 酶原发生自身切割而活化，活化的 caspase-9 再进一步切割并激活 caspase-3 和 caspase-7 酶 原，引发细胞程序性死亡。 ②caspases 非依赖性的细胞程序性死亡 a．凋亡诱导因子（AIF）是诱导 caspases 非依赖性细胞凋亡的蛋白，位于线粒体外膜，在凋 亡过程中，AIF 从线粒体释放进入细胞核，引起核内 DNA 凝集并断裂形成约 5×104 大小的 片段。 b．限制性内切核酸酶 G 属于 Mg2 依赖性的核酸酶家族，受到凋亡信号的刺激后，限制性 ＋   内切核酸酶 G 从线粒体中释放出来进入细胞核，对核 DNA 进行切割，产生典型的以核小体 为单位的 DNA 片段。 c．磷脂酰丝氨酸等信号分子可以启动凋亡细胞的清除过程。", "kp": "ch12_s7_50"}, {"id": "ch12_calc_6", "modI": 3, "q": "试述细胞凋亡的生物学意义与主要研究方法？ 相关试题：“Life is dependent on the cell death，生命依赖于细胞的死亡”，根据这句听起来似 乎是矛盾的悖论，试回答（1）什么是细胞凋亡？（2）细胞凋亡对生命活动（包括生理和病 理）的意义。", "a": "（1）细胞凋亡的生物学意义 参见 16.2 课后习题详解第 2 题。 （2）细胞凋亡常用的研究方法 ①形态学观察 a．台盼蓝染色法 台盼蓝无法进入活细胞，但可使死细胞着色。 b．4′,6-二脒基-2-苯基吲哚（DAPI）染色法 DAPI 是一种能与 DNA 结合的荧光染料，可以染细胞核，借助荧光显微镜，可以观察到细 胞核的形态变化。 c．吉姆萨（Giemsa）染色法 吉姆萨可以使染色质着色，便于在普通光学显微镜下观察到染色质固缩、趋边化、凋亡小体 的形成等凋亡过程。 ②DNA 电泳 细胞凋亡时，染色质 DNA 在核小体间被特异性切割，降解成 180～200bp 或其整数倍片段， 提取的 DNA 在进行琼脂糖凝胶电泳时，呈现出梯状条带。 ③DNA 断裂的原位末端标记法 凋亡细胞的核 DNA 断裂后产生 3′-OH 末端，可借助一种可观测的标记物如荧光素对单个凋 亡细胞核或凋亡小体进行原位染色，用荧光显微镜进行观察；而正常的或正在增殖的细胞几 乎没有 DNA 的断裂，因而没有 3′-OH 形成，很少能够被染色。 ④彗星电泳法 彗星电泳法是指将单个细胞悬浮于琼脂糖凝胶中，经裂解处理后，再在电场中进行短时间的 电泳，并用荧光染料染色来鉴定细胞凋亡的方法。凋亡细胞中的 DNA 降解片段，在电场中 泳动速度较快，使细胞核呈现出一种彗星式的图案，而正常的无 DNA 断裂的核在泳动时保 持圆球形。 ⑤流式细胞分析 凋亡细胞 DNA 发生断裂和丢失，呈亚二倍体状态；采用碘化丙啶染色使 DNA 产生激发荧 光，流式细胞仪能够检测出凋亡的亚二倍体细胞。 ⑥检测细胞膜成分变化 细胞凋亡早期，位于细胞膜内侧的磷脂酰丝氨酸翻转至细胞膜外侧，可以用针对磷脂酰丝氨 酸的荧光标记探针进行检测。 ⑦其他的生理生化方法 检测 caspases 的激活、Cyt c 的释放、线粒体膜电位的变化等。", "kp": "ch12_s3_19"}, {"id": "ch12_calc_7", "modI": 7, "q": "试述细胞凋亡的概念与形态特征，并指出其与坏死的区别是什么？", "a": "（1）细胞凋亡的概念 细胞凋亡是指为维持内环境稳定，由基因控制的细胞自主的有序的死亡。细胞凋亡是主动过 程，涉及一系列基因的激活、表达以及调控等作用，它并不是病理条件下自体损伤的一种现 象，而是为更好地适应生存环境而主动争取的一种死亡过程，最终被吞噬细胞吞噬。细胞凋 亡时在细胞、亚细胞和分子水平上发生了特征性改变。这些改变包括细胞核的改变、细胞器 的改变、细胞膜成分的改变和细胞形态的改变等，其中细胞核的改变最具特征性。 （2）细胞凋亡的形态特征 ①形态学变化 a．凋亡的起始：细胞表面特化结构消失，细胞体积缩小，细胞间接触消失，与周围的细胞 脱离；细胞质密度增加，核质浓缩，核膜、核仁破碎，胞膜有小泡形成，细胞膜结构仍然完 整。 b．凋亡小体的形成：细胞表面产生许多泡状或芽状突起，随后逐渐分隔，形成单个的凋亡 小体，细胞内含物不泄漏到细胞外。 c．吞噬：凋亡小体可迅速被周围专职或非专职吞噬细胞吞噬，在溶酶体内被消化分解。 ②细胞凋亡的生物化学变化 DNA 发生有控降解，片段化的 DNA 片段为 180～200bp 的整倍数；在细胞凋亡的过程中， 常有新基因的表达和某些生物大分子的合成作为调控因子。 （3）细胞凋亡与细胞坏死的区别 细胞凋亡与细胞坏死的区别如表 16-1 所示： 表 16-1 细胞凋亡与细胞坏死的区别 区 细胞凋亡            细胞坏死 别 是 否 由 基是                    否 因 决 定 诱 导                     剧烈损伤或严重的 生理或轻微病理性刺激 因                     病理性刺激 素 形 细胞膜及细胞器相对完整，细胞皱细胞结构全面溶 态 缩，核固缩，有凋亡小体形成，体解、破坏，细胞肿 特 积缩小                 胀，体积膨大 征 生 化DNA 片段化（180～200bp），电泳随机降解，电泳呈 特呈梯状条带                弥散性分布 点 是 否 引 溶酶体破裂，释放 起溶酶体相对完整，不释放内含物， 内含物，局部有炎 炎局部无炎症反应 症反应 症 反 应 染 凝集，形成新月形帽状结构，沿着 色                     不凝集 核膜分布 质", "kp": "ch12_s7_50"}, {"id": "ch12_calc_8", "modI": 7, "q": "动物细胞凋亡的基本途径有哪些？请举例说明。", "a": "动物细胞凋亡的基本途径主要有： （1）caspases 依赖性的细胞凋亡 ①死亡受体介导的细胞凋亡途径 起始于死亡配体与受体的结合，死亡配体主要是肿瘤坏死因子（TNF)家族成员。当细胞接 受凋亡信号分子（FasL、TNF 等）后，凋亡细胞表面信号分子受体相互聚集并与细胞内的 接头蛋白结合，这些接头蛋白又募集 procaspase 聚集在受体部位，procaspase 相互活化并产 生级联反应，使细胞凋亡。 ②线粒体介导的细胞凋亡途径 在这个凋亡途径中细胞色素 c 的释放是关键步骤。当 caspase-8 活化后，它一方面作用于 caspase-3，另一方面使 Bid 裂解成 2 个片段，其中含有 BH3 结构域的 C 端片段被运送到线 粒体，与 Bcl-2／Bax 的 BH3 结构域形成复合物，导致 Cyt c 释放。Cyt c 与 Apaf-1 结合并 活化 Apaf-1，活化的 Apaf-1 再活化 caspase-9，最后引起细胞凋亡。 （2）caspases 非依赖性的细胞凋亡 相对于 caspases 依赖性的细胞凋亡，caspase 非依赖性的细胞凋亡的机制还不完全清楚。已 知线粒体在 caspase 非依赖性的细胞凋亡过程中同样发挥了关键作用。除了细胞色素 c，线 粒体能够向细胞质内释放多个凋亡因子，引发 caspase 非依赖性的细胞凋亡。如凋亡诱导因 子（AIF）和限制性内切核酸酶 G。 （3）穿孔蛋白-颗粒酶介导的细胞凋亡 ①在靶细胞外，颗粒酶 A、B 切割胞外基质蛋白，使靶细胞与基质及周围细胞脱离； ②颗粒酶 A、B 在穿孔蛋白的协助下进入靶细胞切割胞内蛋白，通过 caspases 依赖性和非依 赖性两种方式促使靶细胞凋亡，其中颗粒酶 A 主要通过 caspases 非依赖性细胞凋亡途径； ③颗粒酶 A 通过切割核纤层蛋白和组蛋白破坏细胞核与染色体结构的稳定性，更有利于 DNA 酶的作用。", "kp": "ch12_s7_50"}, {"id": "ch12_calc_9", "modI": 7, "q": "细胞凋亡受到哪些因素的调控？", "a": "细胞凋亡是一个非常复杂的过程，受到机体内、外多种因素的影响，其调控因素分为诱 导性因素和抑制性因素两大类。 （1）诱导性因素 ①生理性诱导因子 肿瘤坏死因子（TNF）及其家族中 Fas 配体（FasL）、转化生长因子β（TGF-β）、神经递质 （谷氨酸，多巴胺，N-甲酰-D-天门冬氨酸）、Ca2 、糖皮质激素等。 ＋   ②理化因素 射线、高温、强酸、强碱、乙醇、抗癌药物等，均可导致细胞凋亡。例如，电离辐射可产生 大量氧自由基，使细胞处于氧化应激状态，DNA 受损，引起细胞凋亡。 ③免疫性因素 在生长、分化及执行防御、自稳、监视功能中，免疫细胞可释放某些分子导致免疫细胞本身 或靶细胞的凋亡。例如，细胞毒性 T 淋巴细胞可分泌颗粒酶，引起靶细胞的凋亡。 ④微生物学因素 细菌、病毒等致病微生物及其毒素可诱导细胞凋亡。如 HIV 感染时，可致大量 CD4 T 淋巴 ＋   细胞凋亡。 ⑤其他因素 热休克、原癌基因（如 myc，rel，腺病毒 E1A 等）、抑癌基因（如野生型 p53 基因）、缺 血、缺氧等。 （2）抑制性因素 ①生理性抑制因子 bcl-2 原癌基因、突变型 p53、各种生长因子、细胞外基质、CD40 配体、一些中性氨基酸、 锌以及雌、雄激素。例如在培养体系中加入所需要的细胞因子，可促进细胞内存活基因的表 达，抑制细胞凋亡的发生。 ②病毒基因 如腺病毒 E1B、杆状病毒、牛痘病毒 crmA、EB 病毒 BHRF1 及 LMP-1、单纯疱疹病毒等基 因。 ③其他因素 线虫的 ced-9 基因、半胱氨酸蛋白酶抑制剂、钙蛋白酶抑制因子、促癌剂（如 PMA 等）。", "kp": "ch12_s7_50"}, {"id": "ch12_calc_10", "modI": 3, "q": "复制衰老的可能机制是什么？", "a": "复制衰老的可能机制是端粒的缩短，即端粒的缩短可以引发细胞的复制衰老。 由于体细胞内缺乏端粒酶活性，随着细胞分裂次数增多，端粒逐渐缩短。端粒的缩短会使细 胞中的 p53 肿瘤抑制因子含量明显增加，继而诱导 p21 的表达，抑制 CDK 的活化，使得 Rb 不能被磷酸化，E2F 处于持续失活状态，细胞不能从 G1 期进入 S 期，最终引发细胞衰老。 具体过程如下： （1）Rb 蛋白能够与转录因子 E2F 家族成员结合并阻止其转录活性，当 E2F 的活性被 Rb 封 闭时，不能正常起始 G1／S 转换过程中若干关键因子的转录，细胞将不进入 S 期而停留在 G1 期。随着细胞周期重要调控因子——CDK 的活化，Rb 被 CDK 磷酸化，磷酸化的 Rb 不 再与 E2F 结合，使得 E2F 被释放并活化靶基因而转录，细胞就从 G1 进入 S 期。 （2）如果 CDK 的正常活化被抑制，或者 Rb 蛋白本身发生突变，导致 Rb 不能被磷酸化， 就会使 G1 期到 S 期的转换被停滞，从而阻断细胞周期的正常运行，引发细胞衰老。", "kp": "ch12_s3_16"}]};